// @cashclinic/web — API client for the Express intake API (:4100).
//
// Mirrors the server DTOs (packages/server/src/routes/intake.ts). The browser
// talks to the same origin via the Vite dev proxy (/api -> :4100), so no
// absolute host is needed in dev. In a built deployment the same origin serves
// the API; the relative paths work either way.
//
// The patient session token is held in memory by the caller (never persisted
// to localStorage/sessionStorage) — consistent with the ephemeral,
// no-PHI-at-rest privacy model (architecture.md §10).

/** A protocol question (mirrors packages/engine Question). */
export interface Question {
  id: string;
  fieldKey: string;
  text: string;
  block: string;
  required: boolean;
  answerType: 'text' | 'boolean' | 'select' | 'number' | 'compound';
  options?: string[];
  parts?: Array<{
    key: string;
    label: string;
    answerType: 'text' | 'boolean' | 'select' | 'number' | 'compound';
    required?: boolean;
    options?: string[];
    conditionalOn?: { key: string; equals: unknown };
  }>;
  conditionalOn?: { fieldKey: string; equals: unknown };
  provenanceKind?: string;
  pertinentNegative?: { whenValue: unknown; label: string };
  clinicalTag?: string;
}

/** Routing state values (mirrors engine SessionState.routingState). */
export type RoutingState = 'unrouted' | 'awaiting_clarification' | 'routed' | 'out_of_scope';

/** Presentation sufficiency state (architecture.md §14.5). */
export type SufficiencyState =
  | 'sufficient_routine'
  | 'sufficient_priority'
  | 'incomplete_patient'
  | 'incomplete_external'
  | 'indeterminate'
  | 'escalation_required'
  | 'outside_scope';

/** A minimal packet shape — the patient UI only needs to know it completed. */
export interface Packet {
  encounterId: string;
  [key: string]: unknown;
}

/**
 * A candidate treatment option as the determination form renders it
 * (normalized from packet.candidateTreatmentOptions; mirrors the shared
 * CandidateTreatmentOption schema but flattened for the UI).
 */
export interface CandidateTreatmentOption {
  id: string;
  label: string;
  description: string;
  /** The authority state string ('provisional_ai_drafted' | 'authorized'). */
  authorityState: string;
}

/** Engine findings surfaced mid-flow (mirrors server FindingsDto). */
export interface FindingsDto {
  escalation: Array<{ ruleId?: string; instruction?: string; reason?: string; [k: string]: unknown }>;
  indeterminacy: Array<{ reason?: string; [k: string]: unknown }>;
  gap: Array<{ description?: string; [k: string]: unknown }>;
}

/** POST /api/intake/session response. */
export interface SessionStartResponse {
  sessionId: string;
  encounterId: string;
  token: string;
  expiresIn: number;
  question: Question;
}

/** POST /api/intake/session/:id/answer response. */
export interface AnswerResponse {
  encounterId: string;
  detectedComplaintId: string | null;
  detectedComplaintLabel: string | null;
  routingState: RoutingState;
  sufficiencyState: SufficiencyState;
  complete: boolean;
  question: Question | null;
  packet: Packet | null;
  findings: FindingsDto;
  escalationInstruction: string;
}

/** POST /api/intake/session/:id/complete response. */
export interface CompleteResponse {
  encounterId: string;
  packet: Packet;
}

/** A structured answer body: { fieldKey, value } OR { freeText }. */
export type AnswerBody =
  | { fieldKey: string; value: unknown }
  | { freeText: string }
  | { fieldKey: string; freeText: string };

/** An error thrown when the API returns a non-2xx status. */
export class ApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly detail: unknown;
  constructor(status: number, code: string, detail: unknown, message: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
    this.detail = detail;
  }
}

const API_ORIGIN = (import.meta.env.VITE_API_BASE_URL ?? '').replace(/\/$/, '');
const API_ROOT = `${API_ORIGIN}/api`;
const API_BASE = `${API_ROOT}/intake`;

function authHeaders(token: string | null): Record<string, string> {
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function parseError(res: Response): Promise<ApiError> {
  let body: unknown = null;
  try {
    body = await res.json();
  } catch {
    body = null;
  }
  let code = `http_${res.status}`;
  let message = res.statusText;
  if (body && typeof body === 'object') {
    const obj = body as Record<string, unknown>;
    if (typeof obj.error === 'string') code = obj.error;
    if (typeof obj.message === 'string') message = obj.message;
  }
  return new ApiError(res.status, code, body, message);
}

/** Start a new patient intake session (no auth required). */
export async function startSession(): Promise<SessionStartResponse> {
  const res = await fetch(`${API_BASE}/session`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: '{}',
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as SessionStartResponse;
}

/** Submit an answer (structured or free-text). Requires the patient token. */
export async function submitAnswer(
  sessionId: string,
  token: string,
  body: AnswerBody,
): Promise<AnswerResponse> {
  const res = await fetch(`${API_BASE}/session/${encodeURIComponent(sessionId)}/answer`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...authHeaders(token),
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as AnswerResponse;
}

/** Finalize the session and assemble the packet. Requires the patient token. */
export async function completeSession(
  sessionId: string,
  token: string,
): Promise<CompleteResponse> {
  const res = await fetch(`${API_BASE}/session/${encodeURIComponent(sessionId)}/complete`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...authHeaders(token),
    },
    body: '{}',
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as CompleteResponse;
}

// ---------------------------------------------------------------------------
// Physician review surface (m4) — auth + review queue + packet + export.
//
// The physician token is held in memory by the caller (never persisted to
// localStorage/sessionStorage), consistent with the no-PHI-at-rest privacy
// model. All /api/review/* and /api/auth/physician/* calls carry the
// physician bearer token (VAL-AUTH-009/011).
// ---------------------------------------------------------------------------

/** A physician login response (mirrors server review.ts). */
export interface PhysicianLoginResponse {
  token: string;
  expiresIn: number;
}

/** A work-unit lane (mirrors server QueueLane). */
export type QueueLane = 'routine' | 'exception';

/** A review-queue summary entry (mirrors server QueueSummaryEntry). */
export interface QueueSummaryEntry {
  packetId: string;
  encounterId: string;
  sufficiencyState: SufficiencyState;
  /** Work-unit lane derived from sufficiencyState (server-computed). */
  lane: QueueLane;
  approvalState: string;
  enqueuedAt: string;
  chiefComplaint: unknown;
  routedComplaintCategory: unknown;
}

/** GET /api/review/queue response. */
export interface ReviewQueueResponse {
  queue: QueueSummaryEntry[];
  count: number;
  /** Lane groupings (both present even when the queue is empty). */
  lanes: {
    routine: QueueSummaryEntry[];
    exception: QueueSummaryEntry[];
  };
  /**
   * Server authorization-gate state (feature item 9): whether provisional
   * treatment options are selectable in a determination. Optional because
   * older servers may not send it; the client treats absence as gate OFF
   * (the safe clinical default).
   */
  allowProvisionalTreatmentOptions?: boolean;
}

/** GET /api/review/:id response. */
export interface ReviewPacketResponse {
  packet: Packet;
  /** Server authorization-gate state (see ReviewQueueResponse). */
  allowProvisionalTreatmentOptions?: boolean;
}

/** A physician determination payload (mirrors server PhysicianDetermination). */
export interface PhysicianDeterminationPayload {
  decision: 'accept' | 'revise' | 'reject';
  diagnosis?: string;
  treatment?: string;
  disposition?: string;
  notes?: string;
  /** Selected candidate treatment option id (structured determination path). */
  selectedOptionId?: string;
  /** Free-text rationale for the "none of these options" override path. */
  overrideRationale?: string;
}

/** POST /api/review/:id/determination response. */
export interface DeterminationResponse {
  packet: Packet;
}

/**
 * Exchange the physician access password for a short-lived physician token
 * (VAL-AUTH-009/010, AUTH-015/016/017). On a wrong password the server
 * returns 401 (VAL-AUTH-010/017).
 */
export async function physicianLogin(password: string): Promise<PhysicianLoginResponse> {
  const res = await fetch(`${API_ROOT}/auth/physician/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ password }),
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as PhysicianLoginResponse;
}

/**
 * Revoke the physician token (logout). VAL-AUTH-018 revocable; the UI uses
 * this to re-gate the review surface (VAL-REVIEW-012).
 */
export async function physicianLogout(token: string): Promise<void> {
  const res = await fetch(`${API_ROOT}/auth/physician/logout`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...authHeaders(token) },
    body: '{}',
  });
  if (!res.ok) throw await parseError(res);
}

/** List pending packets in the review queue (VAL-REVIEW-001/010). */
export async function fetchReviewQueue(token: string): Promise<ReviewQueueResponse> {
  const res = await fetch(`${API_ROOT}/review/queue`, {
    method: 'GET',
    headers: { ...authHeaders(token) },
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as ReviewQueueResponse;
}

/** Fetch a single packet by id (VAL-REVIEW-002/003). */
export async function fetchPacket(packetId: string, token: string): Promise<ReviewPacketResponse> {
  const res = await fetch(`${API_ROOT}/review/${encodeURIComponent(packetId)}`, {
    method: 'GET',
    headers: { ...authHeaders(token) },
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as ReviewPacketResponse;
}

/** Record a physician determination (VAL-REVIEW-007/008, VAL-PROV-011). */
export async function recordDetermination(
  packetId: string,
  token: string,
  determination: PhysicianDeterminationPayload,
): Promise<DeterminationResponse> {
  const res = await fetch(`${API_ROOT}/review/${encodeURIComponent(packetId)}/determination`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...authHeaders(token) },
    body: JSON.stringify(determination),
  });
  if (!res.ok) throw await parseError(res);
  return (await res.json()) as DeterminationResponse;
}

/**
 * Export a packet one-way as JSON or Markdown (VAL-EXPORT-001..004,
 * VAL-PRIV-005/007). Returns the response so the caller can trigger a
 * browser download. The export removes the packet from the queue server-side
 * (VAL-PRIV-005).
 */
export async function exportPacket(
  packetId: string,
  token: string,
  format: 'json' | 'md',
): Promise<{ blob: Blob; filename: string; contentType: string }> {
  const res = await fetch(
    `${API_ROOT}/review/${encodeURIComponent(packetId)}/export?format=${format}`,
    { method: 'GET', headers: { ...authHeaders(token) } },
  );
  if (!res.ok) throw await parseError(res);
  const blob = await res.blob();
  const cd = res.headers.get('Content-Disposition') ?? '';
  const match = /filename="?([^";]+)"?/.exec(cd);
  const filename = match ? match[1] : `${packetId}.${format}`;
  const contentType = res.headers.get('Content-Type') ?? (format === 'md' ? 'text/markdown' : 'application/json');
  return { blob, filename, contentType };
}
