// @cashclinic/web — packet field extraction helpers.
//
// The physician packet (packages/shared/src/packet.ts) is loosely typed at the
// field level (`FieldValue = unknown`) so the engine can own per-complaint
// content shapes. These helpers normalize a field value into a renderable
// shape for the physician UI, preserving:
//   - the explicit absence marker (never fabricating a value, VAL-PACKET-019)
//   - the provenance label on every datum (VAL-PROV-013/015)
//   - derivedFrom references where present (VAL-PROV-008)
//
// The UI only READS and renders; it never reinterprets clinical content
// (VAL-REVIEW-006 — the AI packet is never presented as a decision).

/** A normalized, renderable representation of a single packet datum. */
export interface RenderedDatum {
  /** Stable id for keying (datum id or a synthetic id). */
  id: string;
  /**
   * The question this datum answers, carried VERBATIM from the packet's own
   * `question` property (the engine stamps `question: q.text` — the canonical
   * protocol phrasing from packages/engine/src/protocol/questions.ts — onto
   * every complaint-specific symptom entry and its absence marker).
   *
   * WHY this exists: a boolean-valued datum renders as a bare `yes`, which is
   * clinically useless and dangerous on a surface designed for a ~20-second
   * attestation (VAL-SURFACE-007) — the physician cannot tell WHAT is true
   * without expanding the evidence zone. The question makes the answer
   * actionable in place.
   *
   * `null` when the packet carries no such tie. We NEVER infer or synthesize a
   * label from a fieldKey or from the value's clinical plausibility
   * (.shapes/constraints/4-trustedainofabrication.yaml, VAL-REVIEW-006): an
   * untied datum renders honestly as its bare value rather than as an invented
   * question.
   */
  label: string | null;
  /** Human-readable text representation of the value (or absence label). */
  text: string;
  /** Whether this datum is an explicit absence / "not provided" marker. */
  isAbsent: boolean;
  /** The provenance kind string (or null if unlabeled). */
  provenance: string | null;
  /** Optional derivedFrom datum ids. */
  derivedFrom?: string[];
  /** The raw datum object (for auditability / expansion). */
  raw: unknown;
}

/** Is this value a typed absence-marker object? */
function isAbsenceMarkerObject(value: unknown): boolean {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as { absenceMarker?: unknown }).absenceMarker === 'string'
  );
}

/** Is this value a captured datum object carrying provenance + value? */
function isDatumObject(value: unknown): value is { value?: unknown; provenance?: unknown; id?: string; derivedFrom?: string[] } {
  return (
    typeof value === 'object' &&
    value !== null &&
    !isAbsenceMarkerObject(value) &&
    ('provenance' in (value as Record<string, unknown>))
  );
}

/**
 * Render an unknown scalar value to a display string.
 *
 * Booleans render as `yes` / `no`, not `true` / `false`. The packet only ever
 * carries a boolean as the answer to a question the engine declared
 * `answerType: 'boolean'` (packages/engine/src/protocol/questions.ts), so
 * yes/no is a faithful transliteration of the SAME datum, not an
 * interpretation of it — no clinical content is added (VAL-REVIEW-006).
 */
function scalarText(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'boolean') return value ? 'yes' : 'no';
  if (typeof value === 'number') return String(value);
  return JSON.stringify(value);
}

/**
 * De-snake a coded token the packet itself supplies (e.g. the
 * pregnancyOrNursingStatus `status` enum, `not_pregnant_not_nursing`). This is
 * the same mechanical transform already applied to a bare `absenceMarker`
 * below — it re-spaces the packet's own token and invents nothing.
 */
function humanizeToken(token: string): string {
  return token.replace(/_/g, ' ');
}

/**
 * The question a datum answers, if the packet carries the tie explicitly.
 *
 * Only `question` counts. A `label` is NOT a question label: on a
 * pertinent-negative entry the label is the finished clinical assertion
 * ("denies recent eye surgery") and is rendered as the datum's text, not as a
 * heading for a raw boolean. A fieldKey (`uti_blood_in_urine`) is NOT a
 * question either — expanding it into prose would be fabrication, so an entry
 * carrying only a fieldKey gets no label (VAL-PROV-015).
 */
function datumQuestion(obj: Record<string, unknown>): string | null {
  const q = obj.question;
  return typeof q === 'string' && q.length > 0 ? q : null;
}

/**
 * Extract a display string from a datum object that may use non-standard
 * value properties instead of the typical `value` field. Some packet datums
 * (e.g. workOrAcademicRelease, durationAndProgression) carry their content
 * in dedicated sub-fields rather than a single `value` property. This
 * function checks for those known shapes and falls back to `value` or
 * JSON serialization.
 */
function datumDisplayText(obj: Record<string, unknown>): string {
  // workOrAcademicRelease: { requested, forWhen, ... }
  if (typeof obj.requested === 'boolean' || typeof obj.forWhen === 'string') {
    const parts: string[] = [];
    if (typeof obj.requested === 'boolean') {
      parts.push(obj.requested ? 'Release requested' : 'No release requested');
    }
    if (typeof obj.forWhen === 'string' && obj.forWhen.length > 0) {
      parts.push(`For when: ${obj.forWhen}`);
    }
    if (parts.length > 0) return parts.join(' — ');
  }
  // durationAndProgression: { duration, trajectory, trajectoryHow, ... }
  if (typeof obj.duration === 'string' || typeof obj.trajectory === 'string') {
    const parts: string[] = [];
    if (typeof obj.duration === 'string' && obj.duration.length > 0) parts.push(`Duration: ${obj.duration}`);
    if (typeof obj.trajectory === 'string' && obj.trajectory.length > 0) parts.push(`Trajectory: ${obj.trajectory}`);
    if (typeof obj.trajectoryHow === 'string' && obj.trajectoryHow.length > 0) parts.push(`How: ${obj.trajectoryHow}`);
    if (parts.length > 0) return parts.join(' — ');
  }
  // pregnancyOrNursingStatus: { status } — a coded enum in a dedicated
  // property, with no `value` at all. Without this branch the whole envelope
  // (id, sourceRef, creator, ...) was JSON-dumped into the decision zone's
  // "Pregnancy / nursing" cell (VAL-SURFACE-008).
  if (typeof obj.status === 'string' && obj.status.length > 0) {
    return humanizeToken(obj.status);
  }
  // Pertinent-negative entry: { fieldKey, label, value }. The engine writes
  // `label` from the protocol's pertinentNegative marker, and that label IS
  // the clinical assertion ("denies recent eye surgery"). The accompanying
  // boolean is the marker's encoding — whether the negative is confirmed by
  // `true` or by `false` is a protocol detail, so rendering the raw boolean
  // says nothing and rendering it *beside* the label reads as a contradiction
  // ("denies recent eye surgery — no"). The label alone is the finding
  // (VAL-GATHER-013); the raw datum stays on `raw` for audit.
  if (typeof obj.label === 'string' && obj.label.length > 0 && datumQuestion(obj) === null) {
    return obj.label;
  }
  // Standard datum: use `value`
  if ('value' in obj) return scalarText(obj.value);
  // Fallback: serialize the object (minus provenance/metadata fields)
  return JSON.stringify(obj);
}

/**
 * Normalize a single field value (scalar OR datum object OR absence marker)
 * into a RenderedDatum. Never fabricates content: an absence marker renders
 * as its explicit label (VAL-PACKET-019).
 */
export function renderDatum(value: unknown, fallbackId: string): RenderedDatum {
  if (isAbsenceMarkerObject(value)) {
    const obj = value as { absenceMarker: string; label?: string; provenance?: unknown; id?: string };
    return {
      id: obj.id ?? fallbackId,
      // A missing complaint-specific answer still carries its question, so an
      // unanswered item reads as the clinical thing that was not established
      // rather than as a snake_case fieldKey echo (VAL-PACKET-019).
      label: datumQuestion(value as Record<string, unknown>),
      text: obj.label ?? obj.absenceMarker.replace(/_/g, ' '),
      isAbsent: true,
      provenance: typeof obj.provenance === 'string' ? obj.provenance : null,
      raw: value,
    };
  }
  if (isDatumObject(value)) {
    const obj = value;
    return {
      id: typeof obj.id === 'string' ? obj.id : fallbackId,
      label: datumQuestion(obj as Record<string, unknown>),
      text: datumDisplayText(obj as Record<string, unknown>),
      isAbsent: false,
      provenance: typeof obj.provenance === 'string' ? obj.provenance : null,
      derivedFrom: Array.isArray(obj.derivedFrom) ? obj.derivedFrom : undefined,
      raw: value,
    };
  }
  // Bare scalar / string (e.g. a chief-complaint raw value with no envelope).
  // Also handles objects without provenance/absenceMarker that have
  // display-friendly fields (e.g. missingInformation entries with
  // fieldKey+question, contradiction entries with ruleId+description).
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    const obj = value as Record<string, unknown>;
    // Missing-information entry: { fieldKey, question }
    if (typeof obj.fieldKey === 'string' && typeof obj.question === 'string') {
      return {
        id: fallbackId,
        // The question IS the content of a missing-information / unresolved
        // entry, so it stays in `text`; hoisting it to `label` would leave the
        // row with nothing to say.
        label: null,
        text: `${obj.fieldKey}: ${obj.question}`,
        isAbsent: false,
        provenance: null,
        raw: value,
      };
    }
    // Contradiction entry: { ruleId, description, ... }
    if (typeof obj.ruleId === 'string' && typeof obj.description === 'string') {
      return {
        id: fallbackId,
        label: null,
        text: `${obj.ruleId}: ${obj.description}`,
        isAbsent: false,
        provenance: typeof obj.provenance === 'string' ? obj.provenance : null,
        raw: value,
      };
    }
  }
  return {
    id: fallbackId,
    label: null,
    text: scalarText(value),
    isAbsent: value === null || value === undefined || value === '',
    provenance: null,
    raw: value,
  };
}

/**
 * Normalize a list field (array of datums / absence-marker array / bare
 * scalar) into a list of RenderedDatum. An empty array or a single-element
 * absence-marker array renders as a single explicit "not provided" entry so
 * the field key is never silently omitted (VAL-PACKET-018).
 */
export function renderList(value: unknown, fallbackId: string): RenderedDatum[] {
  if (Array.isArray(value)) {
    if (value.length === 0) {
      return [renderDatum({ absenceMarker: 'none', label: 'none', provenance: 'protocol_escalation' }, `${fallbackId}:absence`)];
    }
    return value.map((item, i) => renderDatum(item, `${fallbackId}:${i}`));
  }
  if (value === null || value === undefined) {
    return [renderDatum({ absenceMarker: 'not_provided', label: 'not provided', provenance: 'protocol_escalation' }, `${fallbackId}:absence`)];
  }
  return [renderDatum(value, fallbackId)];
}

// ---------------------------------------------------------------------------
// Finding extraction — escalation / indeterminacy / gap are distinctly shaped.
// ---------------------------------------------------------------------------

/** A normalized escalation finding (mirrors shared EscalationFinding). */
export interface RenderedEscalation {
  id: string;
  ruleId: string;
  description: string;
  urgency: string;
  requiredCommunication: string;
  currentState: string;
  provenance: string;
}

/** A normalized indeterminacy finding (mirrors shared IndeterminacyFinding). */
export interface RenderedIndeterminacy {
  id: string;
  ruleId: string;
  reason: string;
  kind: string;
  provenance: string;
}

/** A normalized gap finding (mirrors shared Finding). */
export interface RenderedGap {
  id: string;
  ruleId: string;
  description: string;
  provenance: string;
}

/** Read a string field from an unknown object, with a fallback. */
function strField(obj: unknown, key: string, fallback = ''): string {
  if (obj && typeof obj === 'object') {
    const v = (obj as Record<string, unknown>)[key];
    if (typeof v === 'string' && v.length > 0) return v;
  }
  return fallback;
}

/** Normalize the packet's escalationFindings array. */
export function renderEscalations(items: unknown): RenderedEscalation[] {
  if (!Array.isArray(items)) return [];
  return items.map((item, i) => {
    const obj = item as Record<string, unknown> | null;
    return {
      id: strField(obj, 'id', `escalation:${i}`),
      ruleId: strField(obj, 'ruleId', strField(obj, 'firedRuleId', `rule:${i}`)),
      description: strField(obj, 'description'),
      urgency: strField(obj, 'urgency', 'routine'),
      requiredCommunication: strField(obj, 'requiredCommunication'),
      currentState: strField(obj, 'currentState'),
      provenance: 'protocol_escalation',
    };
  });
}

/** Normalize the packet's indeterminacyFindings array. */
export function renderIndeterminacies(items: unknown): RenderedIndeterminacy[] {
  if (!Array.isArray(items)) return [];
  return items.map((item, i) => {
    const obj = item as Record<string, unknown> | null;
    return {
      id: strField(obj, 'id', `indeterminacy:${i}`),
      ruleId: strField(obj, 'ruleId', `rule:${i}`),
      reason: strField(obj, 'reason'),
      kind: strField(obj, 'kind', 'inadequate_characterization'),
      provenance: 'protocol_escalation',
    };
  });
}

/** Normalize the packet's gapFindings array. */
export function renderGaps(items: unknown): RenderedGap[] {
  if (!Array.isArray(items)) return [];
  return items.map((item, i) => {
    const obj = item as Record<string, unknown> | null;
    return {
      id: strField(obj, 'id', `gap:${i}`),
      ruleId: strField(obj, 'ruleId', `gap:${i}`),
      description: strField(obj, 'description'),
      provenance: 'protocol_escalation',
    };
  });
}

// ---------------------------------------------------------------------------
// Packet field descriptor — the full §7 field set, each normalized for render.
// ---------------------------------------------------------------------------

/** A named packet field section for rendering. */
export interface PacketField {
  /** Field key (stable, used for test ids). */
  key: string;
  /** Human-readable section heading. */
  label: string;
  /** Normalized datums (one for scalar fields, many for list fields). */
  data: RenderedDatum[];
  /** Whether this field is a list (multiple entries expected). */
  isList: boolean;
}

/** The full normalized packet for rendering. */
export interface RenderedPacket {
  encounterId: string;
  routedComplaintLabel: string;
  /**
   * Protocol version for the headline: appliedProtocol.complaintVersion,
   * falling back to routedComplaintCategory.version, else 'not recorded'.
   */
  protocolVersion: string;
  sufficiencyState: string;
  dataQualityState: string;
  approvalState: string;
  fields: PacketField[];
  escalations: RenderedEscalation[];
  indeterminacies: RenderedIndeterminacy[];
  gaps: RenderedGap[];
  candidateHpi: RenderedDatum;
  candidateHpiText: string;
  missingInformation: RenderedDatum[];
  contradictoryInformation: RenderedDatum[];
  unresolvedQuestions: RenderedDatum[];
  provenanceAudit: Array<{ field: string; kind: string; sourceRef: string; ruleId?: string; derivedFrom?: string[]; reason?: string }>;
  /**
   * Treatment options the engine withheld because a contraindication fired,
   * derived from the audit entries on `candidateTreatmentOptions.*`
   * (VAL-PROTO-005). A withheld option is otherwise invisible — the option
   * simply is not in the packet — so the physician cannot tell "nothing
   * applies" from "something was taken away and here is why".
   */
  withheldTreatmentOptions: Array<{ optionId: string; ruleId?: string; reason?: string }>;
  physicianDeterminations: Array<Record<string, unknown>>;
}

/** A descriptive label for a routed complaint category object. */
function routedComplaintLabel(value: unknown): string {
  if (value && typeof value === 'object') {
    const obj = value as Record<string, unknown>;
    if (typeof obj.label === 'string' && obj.label.length > 0) return obj.label;
    if (typeof obj.id === 'string' && obj.id.length > 0) return obj.id;
    if (typeof obj.absenceMarker === 'string') return 'not routed';
  }
  if (typeof value === 'string' && value.length > 0) return value;
  return 'not routed';
}

/**
 * Extract the protocol version for the headline (VAL-SURFACE-004). Prefers
 * appliedProtocol.complaintVersion, falls back to routedComplaintCategory.version,
 * and renders an explicit 'not recorded' when neither is present (never
 * fabricates — mirrors the absence-marker contract).
 */
function protocolVersion(packet: Record<string, unknown>): string {
  const ap = packet.appliedProtocol;
  if (ap && typeof ap === 'object') {
    const v = (ap as Record<string, unknown>).complaintVersion;
    if (typeof v === 'string' && v.length > 0) return v;
  }
  const rc = packet.routedComplaintCategory;
  if (rc && typeof rc === 'object') {
    const v = (rc as Record<string, unknown>).version;
    if (typeof v === 'string' && v.length > 0) return v;
  }
  return 'not recorded';
}

/**
 * Normalize a full packet (unknown-typed at the boundary) into a RenderedPacket
 * covering every §7 field. Every required field key is always represented
 * (VAL-PACKET-018): absent data renders as an explicit "not provided" entry.
 */
export function renderPacket(packet: Record<string, unknown>): RenderedPacket {
  const enc = typeof packet.encounterId === 'string' ? packet.encounterId : 'unknown';
  const scalar = (key: string): RenderedDatum => renderDatum(packet[key], `${enc}:${key}`);
  const list = (key: string): RenderedDatum[] => renderList(packet[key], `${enc}:${key}`);

  const fields: PacketField[] = [
    { key: 'chiefComplaint', label: 'Chief complaint', data: [scalar('chiefComplaint')], isList: false },
    { key: 'durationAndProgression', label: 'Duration and progression', data: [scalar('durationAndProgression')], isList: false },
    { key: 'complaintSpecificSymptoms', label: 'Complaint-specific symptoms', data: list('complaintSpecificSymptoms'), isList: true },
    { key: 'pertinentNegatives', label: 'Pertinent negatives', data: list('pertinentNegatives'), isList: true },
    { key: 'relevantMedicalHistory', label: 'Relevant medical history (PMH)', data: [scalar('relevantMedicalHistory')], isList: false },
    { key: 'medications', label: 'Medications (matched to PMH)', data: list('medications'), isList: true },
    { key: 'medicationAllergies', label: 'Medication allergies and reported reactions', data: list('medicationAllergies'), isList: true },
    { key: 'pregnancyOrNursingStatus', label: 'Pregnancy or nursing status', data: [scalar('pregnancyOrNursingStatus')], isList: false },
    { key: 'currentSelfTreatment', label: 'Current self-treatment', data: [scalar('currentSelfTreatment')], isList: false },
    { key: 'measuredTemperature', label: 'Measured temperature', data: [scalar('measuredTemperature')], isList: false },
    { key: 'workOrAcademicRelease', label: 'Work or academic release request (+ for when)', data: [scalar('workOrAcademicRelease')], isList: false },
  ];

  const candidateHpi = scalar('candidateHpi');
  const audit = Array.isArray(packet.provenanceAudit) ? packet.provenanceAudit : [];
  const auditEntries = audit.map((a) => {
    const e = a as Record<string, unknown>;
    return {
      field: typeof e.field === 'string' ? e.field : '',
      kind: typeof e.kind === 'string' ? e.kind : '',
      sourceRef: typeof e.sourceRef === 'string' ? e.sourceRef : '',
      ruleId: typeof e.ruleId === 'string' ? e.ruleId : undefined,
      derivedFrom: Array.isArray(e.derivedFrom) ? (e.derivedFrom as string[]) : undefined,
      reason: typeof e.reason === 'string' ? e.reason : undefined,
    };
  });
  const dets = (packet.physicianDeterminations as unknown);
  const detList = Array.isArray(dets) ? (dets as Array<Record<string, unknown>>) : [];

  return {
    encounterId: enc,
    routedComplaintLabel: routedComplaintLabel(packet.routedComplaintCategory),
    protocolVersion: protocolVersion(packet),
    sufficiencyState: typeof packet.sufficiencyState === 'string' ? packet.sufficiencyState : '',
    dataQualityState: typeof packet.dataQualityState === 'string' ? packet.dataQualityState : '',
    approvalState: typeof packet.approvalState === 'string' ? packet.approvalState : '',
    fields,
    escalations: renderEscalations(packet.escalationFindings),
    indeterminacies: renderIndeterminacies(packet.indeterminacyFindings),
    gaps: renderGaps(packet.gapFindings),
    candidateHpi,
    candidateHpiText: candidateHpi.text,
    missingInformation: list('missingInformation'),
    contradictoryInformation: list('contradictoryInformation'),
    unresolvedQuestions: list('unresolvedQuestions'),
    provenanceAudit: auditEntries,
    // A suppression audit entry is keyed `candidateTreatmentOptions.<optionId>`
    // and is the only record that an option existed and was withheld.
    withheldTreatmentOptions: auditEntries
      .filter((a) => a.field.startsWith('candidateTreatmentOptions.'))
      .map((a) => ({
        optionId: a.field.slice('candidateTreatmentOptions.'.length),
        ruleId: a.ruleId,
        reason: a.reason,
      })),
    physicianDeterminations: detList,
  };
}
