// @cashclinic/web — physician review queue / inbox (m5 queue segregation).
//
// The queue is segregated into two labelled lanes (architecture §8.4,
// VAL-QUI-001..006):
//
//   "Ready to attest"  — entries with sufficiencyState 'sufficient_routine'.
//                        These are the prepared class the 30-second budget
//                        applies to.
//   "Needs attention"  — every other sufficiency state (escalations,
//                        indeterminacy, gaps, incomplete, outside scope).
//
// The lanes are NEVER interleaved: "Ready to attest" renders as one
// contiguous block, "Needs attention" as another (VAL-QUI-004). Mixing them
// would destroy the effective-hour arithmetic.
//
// Each lane renders its own explicit empty affordance when it has no
// entries, so an empty queue shows two empty lanes (VAL-QUI-005) and a
// one-lane-populated queue shows one empty lane + one populated lane
// (VAL-QUI-006). The pre-segregation `queue-empty` testid is preserved as a
// regression net when the whole queue is empty (VAL-REVIEW-010).
//
// Entries remain keyboard-activatable after segregation (VAL-QUI-010): they
// are real <button> elements, so Tab focuses them and Enter/Space activates
// them. The existing `queue-flag-<packetId>` testid and
// `cc-queue-flag-<sufficiencyState>` class hooks are preserved
// (VAL-QUEUE-007).

import type { QueueSummaryEntry, SufficiencyState } from '../api.js';

export interface ReviewQueueProps {
  /** Pending queue entries (server-ordered by priority). */
  entries: QueueSummaryEntry[];
  /** Whether the queue is loading. */
  loading: boolean;
  /** The currently-open packet id (for highlight), or null. */
  openPacketId: string | null;
  /** Called when the physician clicks a queue entry. */
  onOpen: (packetId: string) => void;
  /** Called to refresh the queue. */
  onRefresh: () => void;
}

/** A human-readable label for a sufficiency state. */
const SUFFICIENCY_LABELS: Record<SufficiencyState, string> = {
  sufficient_routine: 'Sufficient — routine',
  sufficient_priority: 'Sufficient — priority',
  incomplete_patient: 'Incomplete (patient)',
  incomplete_external: 'Incomplete (external)',
  indeterminate: 'Indeterminate',
  escalation_required: 'Escalation required',
  outside_scope: 'Outside scope',
};

/** Render the chief-complaint summary text from a queue entry. */
function chiefComplaintText(entry: QueueSummaryEntry): string {
  const cc = entry.chiefComplaint;
  if (cc && typeof cc === 'object' && 'value' in (cc as Record<string, unknown>)) {
    const v = (cc as Record<string, unknown>).value;
    if (typeof v === 'string' && v.length > 0) return v;
  }
  if (typeof cc === 'string' && cc.length > 0) return cc;
  return '(no chief complaint)';
}

/** Render the routed complaint label from a queue entry. */
function routedLabel(entry: QueueSummaryEntry): string {
  const rc = entry.routedComplaintCategory;
  if (rc && typeof rc === 'object' && 'label' in (rc as Record<string, unknown>)) {
    const v = (rc as Record<string, unknown>).label;
    if (typeof v === 'string' && v.length > 0) return v;
  }
  if (typeof rc === 'string' && rc.length > 0) return rc;
  return 'not routed';
}

/** Lane classification: routine ⟺ sufficient_routine; everything else is exception. */
function laneOf(entry: QueueSummaryEntry): 'ready' | 'attention' {
  return entry.sufficiencyState === 'sufficient_routine' ? 'ready' : 'attention';
}

/** Render a single queue entry button (shared by both lanes). */
function QueueEntry({
  entry,
  isOpen,
  onOpen,
}: {
  entry: QueueSummaryEntry;
  isOpen: boolean;
  onOpen: (packetId: string) => void;
}): JSX.Element {
  return (
    <li>
      <button
        type="button"
        className={`cc-queue-entry${isOpen ? ' cc-queue-entry-open' : ''}`}
        onClick={() => onOpen(entry.packetId)}
        data-testid={`queue-entry-${entry.packetId}`}
        aria-pressed={isOpen}
        aria-current={isOpen ? 'true' : undefined}
      >
        <span className="cc-queue-entry-main">
          <span className="cc-queue-entry-cc">{chiefComplaintText(entry)}</span>
          <span className="cc-queue-entry-meta">
            {routedLabel(entry)} · {entry.encounterId}
          </span>
        </span>
        <span
          className={`cc-queue-flag cc-queue-flag-${entry.sufficiencyState}`}
          data-testid={`queue-flag-${entry.packetId}`}
        >
          {SUFFICIENCY_LABELS[entry.sufficiencyState] ?? entry.sufficiencyState}
        </span>
      </button>
    </li>
  );
}

/** Render one labelled lane (heading + entries or empty affordance). */
function Lane({
  testId,
  tone,
  heading,
  entries,
  emptyTestId,
  emptyText,
  openPacketId,
  onOpen,
}: {
  /** Lane container testid. */
  testId: string;
  /** Lane tone modifier ('ready' | 'attention') for the count pill colour. */
  tone: 'ready' | 'attention';
  /** Visible lane heading. */
  heading: string;
  /** Entries routed to this lane. */
  entries: QueueSummaryEntry[];
  /** Empty-state testid for this lane. */
  emptyTestId: string;
  /** Empty-state text for this lane. */
  emptyText: string;
  openPacketId: string | null;
  onOpen: (packetId: string) => void;
}): JSX.Element {
  return (
    <section
      className={`cc-queue-lane cc-queue-lane-${tone}`}
      data-testid={testId}
      aria-label={heading}
    >
      <h3 className="cc-queue-lane-heading">
        {heading}
        {/* The lane load is the number the effective-hour arithmetic runs on;
            surface it next to the heading rather than making it be counted. */}
        <span className="cc-queue-lane-count" data-testid={`${testId}-count`}>
          {entries.length}
        </span>
      </h3>
      {entries.length === 0 ? (
        <p className="cc-queue-lane-empty" data-testid={emptyTestId}>
          {emptyText}
        </p>
      ) : (
        <ul className="cc-queue-list" data-testid={`${testId}-list`}>
          {entries.map((entry) => (
            <QueueEntry
              key={entry.packetId}
              entry={entry}
              isOpen={openPacketId === entry.packetId}
              onOpen={onOpen}
            />
          ))}
        </ul>
      )}
    </section>
  );
}

export function ReviewQueue({ entries, loading, openPacketId, onOpen, onRefresh }: ReviewQueueProps): JSX.Element {
  // Route entries to lanes. The lanes are NEVER interleaved: ready entries
  // form one contiguous block, attention entries another (VAL-QUI-004).
  const readyEntries = entries.filter((e) => laneOf(e) === 'ready');
  const attentionEntries = entries.filter((e) => laneOf(e) === 'attention');

  return (
    <div className="cc-review-queue" data-testid="review-queue">
      <div className="cc-queue-header">
        <h2>Review queue</h2>
        <button
          type="button"
          className="cc-btn cc-btn-ghost"
          onClick={onRefresh}
          data-testid="queue-refresh"
        >
          Refresh
        </button>
      </div>

      {loading ? (
        // VAL-A11Y-009: async status announced via aria-live.
        <p className="cc-help" data-testid="queue-loading" aria-live="polite">
          Loading pending packets...
        </p>
      ) : (
        <>
          {entries.length === 0 ? (
            // VAL-REVIEW-010 (regression): explicit whole-queue empty state.
            <div className="cc-queue-empty" data-testid="queue-empty">
              <p>The review queue is empty.</p>
              <p className="cc-help">
                No pending intake packets. Completed intakes will appear here for review.
              </p>
            </div>
          ) : null}

          {/* "Ready to attest" lane: sufficient_routine entries only. */}
          <Lane
            testId="queue-lane-ready"
            tone="ready"
            heading="Ready to attest"
            entries={readyEntries}
            emptyTestId="queue-lane-ready-empty"
            emptyText="No packets ready to attest."
            openPacketId={openPacketId}
            onOpen={onOpen}
          />

          {/* "Needs attention" lane: every non-routine entry. */}
          <Lane
            testId="queue-lane-attention"
            tone="attention"
            heading="Needs attention"
            entries={attentionEntries}
            emptyTestId="queue-lane-attention-empty"
            emptyText="No packets need attention."
            openPacketId={openPacketId}
            onOpen={onOpen}
          />
        </>
      )}
    </div>
  );
}
