// @cashclinic/web — application root + minimal path router.
//
// Routing is deliberately minimal (no router dependency). The patient intake
// surface is the default; /review is the physician access gate. There is NO
// link from the patient surface to /review, and navigating to /review from the
// patient context lands on the gate with no queue or packet content rendered
// (VAL-CROSS-017).

import { useEffect, useState } from 'react';
import { PatientIntake } from './patient/PatientIntake.js';
import { PhysicianReview } from './physician/PhysicianReview.js';
import './styles.css';

type Route = 'intake' | 'review';

function currentRoute(): Route {
  const path = typeof window !== 'undefined' ? window.location.pathname : '/';
  if (path.startsWith('/review')) return 'review';
  return 'intake';
}

export function App(): JSX.Element {
  const [route, setRoute] = useState<Route>(currentRoute);

  useEffect(() => {
    const onPop = (): void => setRoute(currentRoute());
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  if (route === 'review') {
    return (
      <div className="cc-app cc-app-review">
        <PhysicianReview />
      </div>
    );
  }
  return (
    <div className="cc-app cc-app-intake">
      <PatientIntake />
    </div>
  );
}
