// @cashclinic/web — clarifying-question view.
//
// When the engine cannot commit a complaint route (routingState
// 'awaiting_clarification'), the server returns a question whose `options` are
// the candidate complaint ids (e.g. ["conjunctivitis","stye"]). The patient
// disambiguates by picking one. The UI only proceeds to a specific complaint's
// questions AFTER the patient disambiguates (VAL-INTAKE-030).

import { useState } from 'react';
import type { Question } from '../api.js';

interface ClarifyViewProps {
  question: Question;
  onSubmit: (choice: string) => void;
  onInvalid: (message: string) => void;
  submitting: boolean;
  validationMessage: string | null;
  step?: number;
}

export function ClarifyView({
  question,
  onSubmit,
  onInvalid,
  submitting,
  validationMessage,
  step,
}: ClarifyViewProps): JSX.Element {
  const [choice, setChoice] = useState<string | null>(null);
  const options = question.options ?? [];

  const submit = (): void => {
    if (choice === null) {
      onInvalid('Please choose one of the options to continue.');
      return;
    }
    onSubmit(choice);
  };

  return (
    <div className="cc-screen cc-clarify" role="dialog" aria-labelledby="clarify-label">
      <header className="cc-intake-header">
        <h1>Cashclinic Patient Intake</h1>
      </header>
      <main className="cc-intake-body">
        <fieldset className="cc-question cc-clarify-fieldset" disabled={submitting}>
          {typeof step === 'number' ? (
            <div className="cc-step-tag" aria-label={`step ${step}`}>
              Step {step}
            </div>
          ) : null}
          <h2 id="clarify-label" className="cc-question-text" data-testid="clarify-prompt">
            {question.text}
          </h2>
          <p className="cc-help">
            Your description could match more than one condition. Which sounds closest?
          </p>
          <div className="cc-options" role="radiogroup" aria-labelledby="clarify-label">
            {options.map((opt) => (
              <label
                key={opt}
                className={`cc-option ${choice === opt ? 'cc-option-selected' : ''}`}
                data-testid={`clarify-option-${opt}`}
              >
                <input
                  type="radio"
                  name="clarify_complaint"
                  value={opt}
                  checked={choice === opt}
                  onChange={() => setChoice(opt)}
                />
                <span>{opt.replace(/_/g, ' ')}</span>
              </label>
            ))}
          </div>
          <button
            type="button"
            className="cc-btn cc-btn-primary"
            onClick={submit}
            disabled={choice === null}
            data-testid="clarify-submit"
          >
            Continue
          </button>
        </fieldset>
        {validationMessage ? (
          <p className="cc-validation" role="alert" data-testid="validation-message">
            {validationMessage}
          </p>
        ) : null}
      </main>
    </div>
  );
}
