// @cashclinic/web — provenance badge for the physician review UI.
//
// Renders a field's provenance kind as a visually distinct, human-readable
// label so the physician can distinguish source at a glance (VAL-PROV-015,
// VAL-REVIEW-004). The six kinds map to a closed label + color set so the
// reviewer can never conflate AI-organized/inferred content with
// patient-reported content, and protocol findings are never presented as
// physician determinations (VAL-REVIEW-006).

import type { ProvenanceKind } from '@cashclinic/shared';

/** Display metadata for each provenance kind. */
const PROVENANCE_DISPLAY: Record<ProvenanceKind, { label: string; className: string }> = {
  patient_reported: { label: 'Patient-reported', className: 'cc-prov cc-prov-patient' },
  measured_or_external: { label: 'Measured / external', className: 'cc-prov cc-prov-measured' },
  ai_organized: { label: 'AI-organized', className: 'cc-prov cc-prov-ai-org' },
  ai_inference: { label: 'AI-inference', className: 'cc-prov cc-prov-ai-inf' },
  protocol_escalation: { label: 'Protocol finding', className: 'cc-prov cc-prov-protocol' },
  physician_determination: { label: 'Physician determination', className: 'cc-prov cc-prov-physician' },
};

/**
 * Narrow an unknown value to a ProvenanceKind (the closed six-kind set). Any
 * value outside the set renders as an explicit "unlabeled" badge so a
 * labeling gap is visible rather than hidden (VAL-PROV-001/002).
 */
function asProvenanceKind(value: unknown): ProvenanceKind | null {
  if (
    typeof value === 'string' &&
    [
      'patient_reported',
      'measured_or_external',
      'ai_organized',
      'ai_inference',
      'protocol_escalation',
      'physician_determination',
    ].includes(value)
  ) {
    return value as ProvenanceKind;
  }
  return null;
}

/** Props for a provenance badge. */
export interface ProvenanceBadgeProps {
  /** The provenance kind string from a packet datum / audit entry. */
  provenance: unknown;
  /** Optional data-testid override (defaults to `provenance-badge`). */
  testId?: string;
}

/** Render a single provenance badge. */
export function ProvenanceBadge({ provenance, testId }: ProvenanceBadgeProps): JSX.Element {
  const kind = asProvenanceKind(provenance);
  if (!kind) {
    return (
      <span className="cc-prov cc-prov-unlabeled" data-testid={testId ?? 'provenance-badge'}>
        Unlabeled
      </span>
    );
  }
  const display = PROVENANCE_DISPLAY[kind];
  return (
    <span
      className={display.className}
      data-testid={testId ?? 'provenance-badge'}
      data-provenance={kind}
    >
      {display.label}
    </span>
  );
}
