// @cashclinic/web — completion confirmation view.
//
// Shown when the intake session completes (routine completion, or an
// escalation that stopped the pathway — escalation carries its own notice but
// still reaches completion). The patient sees a plain-language confirmation
// that their intake has been sent for physician review, plus a high-level
// summary of what was captured. No clinical interpretation, diagnosis, or
// treatment is presented — the AI never authors a conclusion (operating rule).
//
// The candidate HPI and the full packet are NOT shown to the patient; they are
// physician-facing only (rendered by the physician review UI behind the access
// gate).

import type { Packet, SufficiencyState } from '../api.js';

interface CompletionViewProps {
  packet: Packet | null;
  encounterId: string;
  detectedComplaintLabel: string | null;
  sufficiencyState: SufficiencyState;
  escalationInstruction: string;
  onRestart: () => void;
}

export function CompletionView({
  packet,
  encounterId,
  detectedComplaintLabel,
  sufficiencyState,
  escalationInstruction,
  onRestart,
}: CompletionViewProps): JSX.Element {
  const missingCount = countMissing(packet);
  return (
    <div className="cc-screen cc-complete" role="status" aria-live="polite">
      <header className="cc-intake-header">
        <h1>Cashclinic Patient Intake</h1>
      </header>
      <main className="cc-intake-body">
        <h2 data-testid="completion-title">Your intake has been sent for physician review</h2>
        <p>
          Thank you. Your responses have been gathered and prepared for your physician to review.
          Your physician will review the packet and follow up with you about next steps.
        </p>
        <ul className="cc-complete-summary" data-testid="completion-summary">
          <li>
            <span className="cc-summary-key">Encounter:</span>{' '}
            <span className="cc-summary-val">{encounterId}</span>
          </li>
          {detectedComplaintLabel ? (
            <li>
              <span className="cc-summary-key">Concern:</span>{' '}
              <span className="cc-summary-val">{detectedComplaintLabel}</span>
            </li>
          ) : null}
          <li>
            <span className="cc-summary-key">Status:</span>{' '}
            <span className="cc-summary-val">{humanSufficiency(sufficiencyState)}</span>
          </li>
          {missingCount > 0 ? (
            <li>
              <span className="cc-summary-key">Items still needed:</span>{' '}
              <span className="cc-summary-val">{missingCount}</span>
              <p className="cc-help">
                Some information could not be obtained; your physician will see these flagged.
              </p>
            </li>
          ) : null}
        </ul>
        {escalationInstruction ? (
          <p className="cc-escalation-instruction" data-testid="completion-escalation">
            {escalationInstruction}
          </p>
        ) : null}
        <p className="cc-privacy-note">
          Your intake was used only for this encounter and has not been stored permanently.
        </p>
        <button type="button" className="cc-btn cc-btn-primary" onClick={onRestart} data-testid="restart">
          Start a new intake
        </button>
      </main>
    </div>
  );
}

function countMissing(packet: Packet | null): number {
  if (!packet) return 0;
  const missing = (packet as { missingInformation?: unknown }).missingInformation;
  if (Array.isArray(missing)) return missing.length;
  return 0;
}

function humanSufficiency(s: SufficiencyState): string {
  switch (s) {
    case 'sufficient_routine':
      return 'Ready for routine physician review';
    case 'sufficient_priority':
      return 'Ready for priority physician review';
    case 'incomplete_patient':
      return 'Incomplete — some information is still needed';
    case 'incomplete_external':
      return 'Incomplete — awaiting external information';
    case 'indeterminate':
      return 'Needs physician consideration';
    case 'escalation_required':
      return 'Flagged for urgent follow-up';
    case 'outside_scope':
      return 'Outside this service\u2019s scope';
    default:
      return s;
  }
}
