// @cashclinic/web — physician packet detail view (m5 decision-surface inversion).
//
// The packet view is split into two zones (architecture §8.1, control sheet
// §5.11 "a concise decision surface first, with evidence beneath it available
// on demand"):
//
//   DECISION ZONE (always visible, in order):
//     1. Headline — routed complaint + protocol version + sufficiency
//     2. Flag summary — escalation / indeterminacy / gap counts, with the
//        escalation findings themselves prominent when present
//     3. Candidate HPI (labelled "AI-drafted candidate — not a physician note")
//     4. Salient positives and explicit negatives
//     5. PMH / medications / allergies / pregnancy-nursing
//     6. Unresolved questions requiring physician judgement
//     7. Determination form — the ONLY determination surface
//
//   EVIDENCE ZONE (native <details>/<summary>, collapsed by default):
//     8. Captured intake data (the 11 field sections)
//     9. Provenance audit
//    10. Prior recorded determinations
//    11. Export (one-way)
//
// Disclosure is native browser behavior only — no useState controls the
// disclosure (VAL-SURFACE-011). Every pre-inversion data-testid is preserved
// (VAL-SURFACE-025).
//
// The AI packet is NEVER presented as a decision (VAL-REVIEW-006,
// VAL-SURFACE-023): AI-derived content carries AI provenance badges, findings
// carry protocol-escalation badges, and the only determination surface is the
// physician's own DeterminationForm.
//
// Export is one-way and user-initiated (VAL-EXPORT-001..004): clicking an
// export button triggers a browser download. Export does NOT remove the packet
// — the server deliberately leaves it in place so both formats can be exported
// from the same packet (see the note at the end of GET /:id/export). What
// removes a case from the pending queue is recording a determination
// (VAL-PRIV-005): list() filters entries that have one. Entries also expire by
// TTL (VAL-PRIV-006). The physician is warned about the irreversible action —
// the determination — not about the reversible one.

import { useEffect, useRef, useState } from 'react';
import type { Packet, CandidateTreatmentOption } from '../api.js';
import { exportPacket, ApiError } from '../api.js';
import { ProvenanceBadge } from './ProvenanceBadge.js';
import { DeterminationForm } from './DeterminationForm.js';
import {
  renderPacket,
  type RenderedDatum,
  type PacketField,
  type RenderedPacket,
} from './packet-render.js';

export interface PacketViewProps {
  /** The packet id (= encounter id). */
  packetId: string;
  /** The packet JSON object. */
  packet: Packet;
  /** Physician token (in-memory). */
  token: string;
  /** Called with the updated packet after a determination is recorded. */
  onDeterminationRecorded: (packet: Packet) => void;
  /** Called after a successful export (packet removed from queue). */
  onExported: () => void;
  /**
   * Called when the physician clicks "Back to queue". Distinct from
   * onExported: back must NOT trigger export (VAL-SURFACE-024). Optional so
   * existing callers/tests that predate the inversion keep working; when
   * absent the button falls back to onExported's return-to-queue behavior.
   */
  onBack?: () => void;
  /**
   * Server authorization-gate state (feature item 9): whether provisional
   * treatment options are selectable. Optional because older callers/tests
   * may not pass it; absence means gate OFF (the safe clinical default).
   */
  allowProvisionalTreatmentOptions?: boolean;
}

/**
 * Render a single RenderedDatum row with its provenance badge.
 *
 * When the packet ties the datum to the question it answers, that question
 * leads the row and the answer follows it (VAL-SURFACE-007). Without it a
 * boolean datum renders as a bare `yes` — unreadable on a decision surface
 * budgeted at ~20 seconds, because establishing what the assertion refers to
 * forces the physician into the evidence zone. The question is carried
 * verbatim from the packet and is `null` when the packet does not establish
 * the tie, so nothing is ever invented (VAL-PROV-015, VAL-REVIEW-006).
 *
 * The provenance badge stays attached to every datum either way
 * (VAL-PROV-013/015) — the label is added beside it, never in place of it.
 */
function DatumRow({ datum, testId }: { datum: RenderedDatum; testId: string }): JSX.Element {
  return (
    <li className="cc-datum-row" data-testid={testId}>
      {datum.label ? (
        <span className="cc-datum-label" data-testid={`${testId}-label`}>
          {datum.label}
        </span>
      ) : null}
      {/* An absent answer is not a finding to emphasise — it keeps the muted
          absence treatment rather than the answer weight. */}
      <span
        className={`cc-datum-text${datum.label && !datum.isAbsent ? ' cc-datum-answer' : ''}${datum.isAbsent ? ' cc-datum-absent' : ''}`}
        data-testid={`${testId}-text`}
      >
        {datum.isAbsent ? `(${datum.text})` : datum.text || '(empty)'}
      </span>
      {datum.provenance ? (
        <ProvenanceBadge provenance={datum.provenance} testId={`${testId}-prov`} />
      ) : null}
      {datum.derivedFrom && datum.derivedFrom.length > 0 ? (
        <span className="cc-datum-derived" data-testid={`${testId}-derived`}>
          derived from: {datum.derivedFrom.join(', ')}
        </span>
      ) : null}
    </li>
  );
}

/**
 * Render a packet field section (scalar or list) inside the evidence zone.
 * Uses h4 because these sections nest inside the h3-headed "Captured intake
 * data" section — no h3 inside h3 (VAL-A11Y-002).
 */
function FieldSection({ field }: { field: PacketField }): JSX.Element {
  return (
    <section className="cc-field-section" data-testid={`field-${field.key}`}>
      <h4 className="cc-section-heading">{field.label}</h4>
      <ul className="cc-datum-list">
        {field.data.map((datum, i) => (
          <DatumRow
            key={datum.id + i}
            datum={datum}
            testId={`field-${field.key}-${i}`}
          />
        ))}
      </ul>
    </section>
  );
}

/**
 * A headline metadata chip. The headline reads as a row of labelled chips
 * rather than a run-on sentence; `tone` opts a chip into a semantic colour
 * (e.g. the sufficiency state) so the packet's standing is legible at a
 * glance.
 */
function MetaChip({
  label,
  value,
  tone,
  testId,
}: {
  label: string;
  value: string;
  /** 'strong' for the routed complaint, or a state token for semantic colour. */
  tone?: string;
  testId: string;
}): JSX.Element {
  return (
    <span className={`cc-meta-chip${tone ? ` cc-meta-chip-${tone}` : ''}`} data-testid={testId}>
      <span className="cc-meta-chip-key">{label}</span>
      {value}
    </span>
  );
}

/** Look up a rendered field by key (fields are a keyed, reorderable array). */
function fieldByKey(rendered: RenderedPacket, key: string): PacketField | undefined {
  return rendered.fields.find((f) => f.key === key);
}

/** Join a field's datum texts into a compact one-line summary. */
function fieldSummary(field: PacketField | undefined): string {
  if (!field) return 'not provided';
  const texts = field.data.map((d) => d.text).filter((t) => t.length > 0);
  if (texts.length === 0) return 'not provided';
  return texts.join('; ');
}

/**
 * Class suffix marking a zero-count flag chip. Colour is meaning here: a chip
 * only wears its semantic colour when the finding actually fired.
 */
function zeroClass(count: number): string {
  return count === 0 ? ' cc-flag-count-zero' : '';
}

/** Class suffix collapsing an empty findings section to a quiet inline strip. */
function emptyClass(count: number): string {
  return count === 0 ? ' cc-flags-empty' : '';
}

/**
 * Whether a detected-problems list has nothing to report. A single absence
 * datum ("none recorded") is an empty list, not a finding — same rule the
 * pre-inversion view applied inline.
 */
function problemsEmpty(data: RenderedDatum[]): boolean {
  return data.length === 0 || (data.length === 1 && data[0].isAbsent);
}

/** Whether a field carries any non-absent datum (used to mark absent context). */
function fieldHasContent(field: PacketField | undefined): boolean {
  if (!field) return false;
  return field.data.some((d) => !d.isAbsent && d.text.length > 0);
}

export function PacketView({
  packetId,
  packet,
  token,
  onDeterminationRecorded,
  onExported,
  onBack,
  allowProvisionalTreatmentOptions,
}: PacketViewProps): JSX.Element {
  const [exporting, setExporting] = useState<'json' | 'md' | null>(null);
  const [exportError, setExportError] = useState<string | null>(null);
  const [lastExport, setLastExport] = useState<string | null>(null);
  // The packet may be mutated in-place by the determination recorder; keep a
  // local copy so the view re-renders with the updated packet (including the
  // newly-attached physician_determination).
  const [current, setCurrent] = useState<Packet>(packet);
  // VAL-A11Y-004: programmatic focus target for the packet heading on open.
  const titleRef = useRef<HTMLHeadingElement>(null);

  // Move focus to the packet heading when the packet opens so keyboard and
  // screen-reader users land at the start of the detail view (VAL-A11Y-004).
  // tabIndex=-1 makes the heading programmatically focusable without adding
  // it to the Tab order.
  useEffect(() => {
    titleRef.current?.focus();
  }, []);

  const rendered = renderPacket(current as unknown as Record<string, unknown>);

  // Candidate treatment options for the determination form (VAL-SURFACE-014).
  // The packet field is loosely typed at the boundary; normalize to the
  // option shape the form needs, ignoring malformed entries.
  const rawOptions = (current as unknown as Record<string, unknown>).candidateTreatmentOptions;
  const candidateTreatmentOptions: CandidateTreatmentOption[] = Array.isArray(rawOptions)
    ? rawOptions
        .map((o) => o as Record<string, unknown>)
        .filter(
          (o) =>
            typeof o?.id === 'string' &&
            typeof o?.label === 'string' &&
            typeof (o?.authority as Record<string, unknown> | undefined)?.state === 'string',
        )
        .map((o) => ({
          id: o.id as string,
          label: o.label as string,
          description: typeof o.description === 'string' ? o.description : '',
          authorityState: (o.authority as Record<string, unknown>).state as string,
        }))
    : [];

  function triggerDownload(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  async function doExport(format: 'json' | 'md'): Promise<void> {
    setExportError(null);
    setExporting(format);
    try {
      const { blob, filename } = await exportPacket(packetId, token, format);
      // VAL-EXPORT-001..004: user-initiated one-way download.
      triggerDownload(blob, filename);
      setLastExport(`${format.toUpperCase()} exported: ${filename}`);
      // VAL-PRIV-005: a successful export removes the packet from the queue.
      onExported();
    } catch (e) {
      if (e instanceof ApiError) {
        setExportError(`Export failed (${e.code}). The packet may have already been exported.`);
      } else {
        setExportError('Could not reach the server for export.');
      }
    } finally {
      setExporting(null);
    }
  }

  // Back must return to the queue, never trigger export (VAL-SURFACE-024).
  const handleBack = onBack ?? onExported;

  return (
    <article className="cc-packet" data-testid="packet-view" data-packet-id={packetId}>
      {/* ==============================================================
          DECISION ZONE — always visible, decision-surface first.
          ============================================================== */}
      <div className="cc-decision-zone" data-testid="decision-zone">
        {/* 1. Headline: routed complaint + protocol version + sufficiency. */}
        <header className="cc-packet-header" data-testid="packet-headline">
          <button
            type="button"
            className="cc-btn cc-btn-ghost cc-packet-back"
            onClick={handleBack}
            data-testid="packet-back"
          >
            <span aria-hidden="true">← </span>Back to queue
          </button>
          <h2 ref={titleRef} tabIndex={-1} data-testid="packet-title">
            Packet · {rendered.encounterId}
          </h2>
          <p className="cc-packet-meta" data-testid="packet-meta">
            <MetaChip
              label="Routed"
              value={rendered.routedComplaintLabel}
              tone="strong"
              testId="packet-routed"
            />
            <MetaChip
              label="Protocol"
              value={rendered.protocolVersion}
              testId="packet-protocol-version"
            />
            <MetaChip
              label="Sufficiency"
              value={rendered.sufficiencyState}
              tone={rendered.sufficiencyState}
              testId="packet-sufficiency"
            />
            <MetaChip label="Data" value={rendered.dataQualityState} testId="packet-data-quality" />
            <MetaChip label="Approval" value={rendered.approvalState} testId="packet-approval" />
          </p>
        </header>

        {/* The working area: the clinical picture the physician reads, with
            their own determination panel pinned alongside it. This is a layout
            wrapper only — DOM order is unchanged (VAL-SURFACE-001/003). */}
        <div className="cc-decision-grid">
          <div className="cc-decision-main">
            {/* 2. Flag summary: escalation / indeterminacy / gap counts at a
                glance, then the findings themselves (escalation findings stay
                prominent in the decision zone — VAL-SURFACE-006). Colour is
                dropped on a zero count so only fired findings carry it. */}
            <section className="cc-flag-summary" data-testid="flag-summary" aria-label="Flag summary">
              <span
                className={`cc-flag-count cc-flag-count-escalation${zeroClass(rendered.escalations.length)}`}
                data-testid="flag-count-escalation"
              >
                <span aria-hidden="true">⚠ </span>Escalation: {rendered.escalations.length}
              </span>
              <span
                className={`cc-flag-count cc-flag-count-indeterminacy${zeroClass(rendered.indeterminacies.length)}`}
                data-testid="flag-count-indeterminacy"
              >
                <span aria-hidden="true">? </span>Indeterminacy: {rendered.indeterminacies.length}
              </span>
              <span
                className={`cc-flag-count cc-flag-count-gap${zeroClass(rendered.gaps.length)}`}
                data-testid="flag-count-gap"
              >
                <span aria-hidden="true">○ </span>Gap: {rendered.gaps.length}
              </span>
            </section>

            {/* Clearly distinguished escalation / indeterminacy / gap findings.
                Each is its own labeled, color-coded section so the physician
                can tell them apart at a glance (VAL-REVIEW-005, VAL-ESC-008,
                VAL-INDET-008, VAL-GAP-006). A section with no findings keeps
                its heading and testid but collapses to a quiet inline strip,
                so an unremarkable packet reads as unremarkable. */}
            <div className="cc-flag-sections">
              <section
                className={`cc-flags cc-flags-escalation${emptyClass(rendered.escalations.length)}`}
                data-testid="flags-escalation"
                aria-label="Escalation findings"
              >
                <h3 className="cc-flag-heading">
                  <span aria-hidden="true">⚠ </span>Escalation findings
                </h3>
                {rendered.escalations.length === 0 ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-flag-list">
                    {rendered.escalations.map((f) => (
                      <li key={f.id} className="cc-flag-item" data-testid="escalation-item">
                        <span className="cc-flag-rule" data-testid="escalation-rule">
                          Rule: {f.ruleId}
                        </span>
                        <span className="cc-flag-desc" data-testid="escalation-desc">
                          {f.description}
                        </span>
                        <span className="cc-flag-detail">
                          Urgency: {f.urgency}
                          {f.requiredCommunication ? ` · Communication: ${f.requiredCommunication}` : ''}
                          {f.currentState ? ` · State: ${f.currentState}` : ''}
                        </span>
                        <ProvenanceBadge provenance={f.provenance} testId="escalation-prov" />
                      </li>
                    ))}
                  </ul>
                )}
              </section>

              <section
                className={`cc-flags cc-flags-indeterminacy${emptyClass(rendered.indeterminacies.length)}`}
                data-testid="flags-indeterminacy"
                aria-label="Indeterminacy findings"
              >
                <h3 className="cc-flag-heading">
                  <span aria-hidden="true">? </span>Indeterminacy findings
                </h3>
                {rendered.indeterminacies.length === 0 ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-flag-list">
                    {rendered.indeterminacies.map((f) => (
                      <li key={f.id} className="cc-flag-item" data-testid="indeterminacy-item">
                        <span className="cc-flag-rule" data-testid="indeterminacy-rule">
                          Rule: {f.ruleId}
                        </span>
                        <span className="cc-flag-desc" data-testid="indeterminacy-reason">
                          Reason: {f.reason}
                        </span>
                        <span className="cc-flag-detail">Kind: {f.kind}</span>
                        <ProvenanceBadge provenance={f.provenance} testId="indeterminacy-prov" />
                      </li>
                    ))}
                  </ul>
                )}
              </section>

              <section
                className={`cc-flags cc-flags-gap${emptyClass(rendered.gaps.length)}`}
                data-testid="flags-gap"
                aria-label="Gap findings (protocol-undefined areas)"
              >
                <h3 className="cc-flag-heading">
                  <span aria-hidden="true">○ </span>Gap findings (protocol-undefined areas)
                </h3>
                {rendered.gaps.length === 0 ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-flag-list">
                    {rendered.gaps.map((f) => (
                      <li key={f.id} className="cc-flag-item" data-testid="gap-item">
                        <span className="cc-flag-rule" data-testid="gap-rule">
                          Marker: {f.ruleId}
                        </span>
                        <span className="cc-flag-desc" data-testid="gap-desc">
                          {f.description}
                        </span>
                        <ProvenanceBadge provenance={f.provenance} testId="gap-prov" />
                      </li>
                    ))}
                  </ul>
                )}
              </section>
            </div>

            {/* 3. Candidate HPI — labeled as AI-drafted candidate, never a
                decision (VAL-HPI-006, VAL-REVIEW-006, VAL-SURFACE-023). */}
            <section className="cc-candidate-hpi" data-testid="candidate-hpi">
              <h3 className="cc-section-heading">Candidate HPI summary</h3>
              <p className="cc-candidate-label" data-testid="candidate-hpi-label">
                AI-drafted candidate — not a physician note. Verify against captured data.
              </p>
              <blockquote className="cc-candidate-text" data-testid="candidate-hpi-text">
                {rendered.candidateHpi.isAbsent
                  ? `(no candidate HPI — ${rendered.candidateHpiText})`
                  : rendered.candidateHpiText || '(empty)'}
              </blockquote>
              {rendered.candidateHpi.provenance ? (
                <ProvenanceBadge
                  provenance={rendered.candidateHpi.provenance}
                  testId="candidate-hpi-prov"
                />
              ) : null}
            </section>

            {/* 4. Salient positives and explicit negatives — the salient
                picture at a glance (VAL-SURFACE-007). */}
            <section className="cc-salient" data-testid="salient-summary" aria-label="Salient findings">
              <h3 className="cc-section-heading">Salient findings</h3>
              <div className="cc-salient-block" data-testid="salient-positives">
                <h4 className="cc-salient-heading">Salient positives</h4>
                <ul className="cc-datum-list">
                  {(fieldByKey(rendered, 'complaintSpecificSymptoms')?.data ?? []).map((d, i) => (
                    <DatumRow key={d.id + i} datum={d} testId={`salient-positive-${i}`} />
                  ))}
                </ul>
              </div>
              <div className="cc-salient-block" data-testid="explicit-negatives">
                <h4 className="cc-salient-heading">Explicit negatives</h4>
                <ul className="cc-datum-list">
                  {(fieldByKey(rendered, 'pertinentNegatives')?.data ?? []).map((d, i) => (
                    <DatumRow key={d.id + i} datum={d} testId={`explicit-negative-${i}`} />
                  ))}
                </ul>
              </div>
            </section>

            {/* 5. Relevant PMH, medications, allergies, pregnancy/nursing
                (VAL-SURFACE-008). */}
            <section className="cc-clinical-context" data-testid="clinical-context" aria-label="Clinical context">
              <h3 className="cc-section-heading">Clinical context</h3>
              <dl className="cc-context-grid">
                <div className="cc-context-item" data-testid="context-pmh">
                  <dt>PMH</dt>
                  <dd className={fieldHasContent(fieldByKey(rendered, 'relevantMedicalHistory')) ? '' : 'cc-datum-absent'}>
                    {fieldSummary(fieldByKey(rendered, 'relevantMedicalHistory'))}
                  </dd>
                </div>
                <div className="cc-context-item" data-testid="context-medications">
                  <dt>Medications</dt>
                  <dd className={fieldHasContent(fieldByKey(rendered, 'medications')) ? '' : 'cc-datum-absent'}>
                    {fieldSummary(fieldByKey(rendered, 'medications'))}
                  </dd>
                </div>
                <div className="cc-context-item" data-testid="context-allergies">
                  <dt>Allergies</dt>
                  <dd className={fieldHasContent(fieldByKey(rendered, 'medicationAllergies')) ? '' : 'cc-datum-absent'}>
                    {fieldSummary(fieldByKey(rendered, 'medicationAllergies'))}
                  </dd>
                </div>
                <div className="cc-context-item" data-testid="context-pregnancy">
                  <dt>Pregnancy / nursing</dt>
                  <dd className={fieldHasContent(fieldByKey(rendered, 'pregnancyOrNursingStatus')) ? '' : 'cc-datum-absent'}>
                    {fieldSummary(fieldByKey(rendered, 'pregnancyOrNursingStatus'))}
                  </dd>
                </div>
              </dl>
            </section>

            {/* Detected problems: missing / contradictory stay available; the
                unresolved questions are part of the decision surface (§8.1.6).
                Each collapses to a quiet strip when it has nothing to say. */}
            <div className="cc-problem-grid">
              <section
                className={`cc-problems${problemsEmpty(rendered.missingInformation) ? ' cc-problems-empty' : ''}`}
                data-testid="problems-missing"
              >
                <h3 className="cc-section-heading">Missing information</h3>
                {problemsEmpty(rendered.missingInformation) ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-datum-list">
                    {rendered.missingInformation.map((d, i) => (
                      <DatumRow key={d.id + i} datum={d} testId={`missing-${i}`} />
                    ))}
                  </ul>
                )}
              </section>

              <section
                className={`cc-problems${problemsEmpty(rendered.contradictoryInformation) ? ' cc-problems-empty' : ''}`}
                data-testid="problems-contradictory"
              >
                <h3 className="cc-section-heading">Contradictory information</h3>
                {problemsEmpty(rendered.contradictoryInformation) ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-datum-list">
                    {rendered.contradictoryInformation.map((d, i) => (
                      <DatumRow key={d.id + i} datum={d} testId={`contradictory-${i}`} />
                    ))}
                  </ul>
                )}
              </section>

              {/* 6. Unresolved questions requiring physician judgement. */}
              <section
                className={`cc-problems${problemsEmpty(rendered.unresolvedQuestions) ? ' cc-problems-empty' : ''}`}
                data-testid="problems-unresolved"
              >
                <h3 className="cc-section-heading">Unresolved questions requiring physician consideration</h3>
                {problemsEmpty(rendered.unresolvedQuestions) ? (
                  <p className="cc-flag-none">None.</p>
                ) : (
                  <ul className="cc-datum-list">
                    {rendered.unresolvedQuestions.map((d, i) => (
                      <DatumRow key={d.id + i} datum={d} testId={`unresolved-${i}`} />
                    ))}
                  </ul>
                )}
              </section>
            </div>
          </div>

          {/* 7. The ONLY determination surface (VAL-PROV-011/012,
              VAL-REVIEW-007), pinned beside the clinical picture so the
              physician never scrolls away from it. Candidate treatment options
              render here as selectable controls with visible authority labels
              (VAL-SURFACE-014..020). */}
          <div className="cc-decision-side">
            <DeterminationForm
              packetId={packetId}
              token={token}
              candidateTreatmentOptions={candidateTreatmentOptions}
              withheldTreatmentOptions={rendered.withheldTreatmentOptions}
              allowProvisionalTreatmentOptions={allowProvisionalTreatmentOptions ?? false}
              onRecorded={(updated) => {
                setCurrent(updated);
                onDeterminationRecorded(updated);
              }}
            />
          </div>
        </div>
      </div>

      {/* ==============================================================
          EVIDENCE ZONE — collapsed by default, native disclosure only.
          ============================================================== */}
      <details className="cc-evidence-zone" data-testid="evidence-zone">
        <summary className="cc-evidence-summary" data-testid="evidence-summary">
          Evidence — captured intake data, provenance audit, prior determinations, export
        </summary>

        <div className="cc-evidence-body">
          {/* 8. Captured data — every §7 field with provenance labels. */}
          <section className="cc-captured" data-testid="captured-fields">
            <h3 className="cc-section-heading">Captured intake data</h3>
            {rendered.fields.map((field) => (
              <FieldSection key={field.key} field={field} />
            ))}
          </section>

          {/* 9. Provenance audit (machine-readable, inspectable in the UI). */}
          <section className="cc-audit" data-testid="provenance-audit">
            <h3 className="cc-section-heading">Provenance audit</h3>
            {rendered.provenanceAudit.length === 0 ? (
              <p className="cc-flag-none">No audit entries.</p>
            ) : (
              <ul className="cc-audit-list">
                {rendered.provenanceAudit.map((a, i) => (
                  <li key={`${a.field}-${i}`} className="cc-audit-row" data-testid={`audit-${i}`}>
                    <span className="cc-audit-field">{a.field || '(field)'}</span>
                    <ProvenanceBadge provenance={a.kind} testId={`audit-${i}-prov`} />
                    <span className="cc-audit-source">{a.sourceRef}</span>
                    {a.ruleId ? <span className="cc-audit-rule">rule: {a.ruleId}</span> : null}
                    {a.derivedFrom && a.derivedFrom.length > 0 ? (
                      <span className="cc-audit-derived">derived: {a.derivedFrom.join(', ')}</span>
                    ) : null}
                  </li>
                ))}
              </ul>
            )}
          </section>

          {/* 10. Recorded physician determinations (if any). */}
          {rendered.physicianDeterminations.length > 0 ? (
            <section className="cc-determinations" data-testid="recorded-determinations">
              <h3 className="cc-section-heading">Recorded physician determinations</h3>
              <ul className="cc-datum-list">
                {rendered.physicianDeterminations.map((d, i) => {
                  const fields = (d.fields as Record<string, unknown> | undefined) ?? {};
                  return (
                    <li key={i} className="cc-datum-row" data-testid={`recorded-det-${i}`}>
                      <span className="cc-datum-text">
                        Decision: {String(d.decision ?? '?')} · recorded {String(d.recordedAt ?? '?')}
                      </span>
                      {d.provisional === true ? (
                        <span className="cc-det-provisional" data-testid={`recorded-det-${i}-provisional`}>
                          provisional — not clinically authorized
                        </span>
                      ) : null}
                      <ProvenanceBadge provenance="physician_determination" testId={`recorded-det-${i}-prov`} />
                      <ul className="cc-det-fields">
                        {typeof d.selectedOptionId === 'string' && d.selectedOptionId ? (
                          <li data-testid={`recorded-det-${i}-selectedOptionId`}>
                            selectedOptionId: {d.selectedOptionId}
                          </li>
                        ) : null}
                        {typeof d.optionAuthorityBasis === 'string' && d.optionAuthorityBasis ? (
                          <li data-testid={`recorded-det-${i}-optionAuthorityBasis`}>
                            optionAuthorityBasis: {d.optionAuthorityBasis}
                          </li>
                        ) : null}
                        {typeof d.overrideRationale === 'string' && d.overrideRationale ? (
                          <li data-testid={`recorded-det-${i}-overrideRationale`}>
                            overrideRationale: {d.overrideRationale}
                          </li>
                        ) : null}
                        {Object.entries(fields).map(([k, v]) => {
                          const val = (v as Record<string, unknown>)?.value;
                          return (
                            <li key={k} data-testid={`recorded-det-${i}-${k}`}>
                              {k}: {String(val ?? '')}
                            </li>
                          );
                        })}
                      </ul>
                    </li>
                  );
                })}
              </ul>
            </section>
          ) : null}

          {/* 11. One-way, user-initiated export (VAL-EXPORT-001..004). */}
          <section className="cc-export" data-testid="export-section">
            <h3 className="cc-section-heading">Export (one-way)</h3>
            <p className="cc-help">
              Export is outbound only — there is no re-import. Exporting does not record a
              decision and does not remove this packet from the queue; both formats can be
              exported from the same packet.
            </p>
            <div className="cc-export-row">
              <button
                type="button"
                className="cc-btn"
                onClick={() => doExport('json')}
                disabled={exporting !== null}
                data-testid="export-json"
              >
                {exporting === 'json' ? 'Exporting...' : 'Export JSON'}
              </button>
              <button
                type="button"
                className="cc-btn"
                onClick={() => doExport('md')}
                disabled={exporting !== null}
                data-testid="export-md"
              >
                {exporting === 'md' ? 'Exporting...' : 'Export Markdown'}
              </button>
            </div>
            {/* VAL-A11Y-009: the export result is async status, announced via
                a dedicated polite live region. */}
            <div data-testid="export-result-region" aria-live="polite">
              {lastExport ? (
                <p className="cc-flow-hint" data-testid="export-result">
                  {lastExport}
                </p>
              ) : null}
            </div>
            {exportError ? (
              <p className="cc-validation" role="alert" data-testid="export-error">
                {exportError}
              </p>
            ) : null}
          </section>
        </div>
      </details>
    </article>
  );
}
