// @cashclinic/web — physician determination form.
//
// The ONLY place in the UI where `physician_determination` provenance is
// produced (VAL-PROV-011/012, VAL-REVIEW-007/008). The physician records
// their adjudication of the case (diagnosis / treatment / disposition /
// notes + an accept/revise/reject decision). Submitting calls
// POST /api/review/:id/determination; the server tags the fields
// `physician_determination` and attributes them to the physician — never to
// AI (VAL-REVIEW-008). The AI packet above is never presented as a decision
// (VAL-REVIEW-006); this form is explicitly the physician's own input.
//
// m5 adds the candidate treatment option selection (architecture §8.1.7,
// §6): the engine's drafted options render as selectable radio controls
// (VAL-SURFACE-014), each with a visible authority label (VAL-SURFACE-015).
// Provisional options carry a distinct class (VAL-SURFACE-016) and a warning
// that they are not clinically authorized. The authorization gate is
// server-side; the UI only reflects it: with the gate off provisional
// options are rendered but disabled so they cannot be activated
// (VAL-SURFACE-017); with the gate on they become selectable while the
// warning persists (VAL-SURFACE-018). The free-text override path (no
// option selected, optional overrideRationale) is always available
// (VAL-SURFACE-021, VAL-DET-003/005). Controls are mouse-first but fully
// keyboard navigable (native radios: Tab + Space/Arrows — feature item 10).

import { useId, useState } from 'react';
import {
  recordDetermination,
  type PhysicianDeterminationPayload,
  type Packet,
  type CandidateTreatmentOption,
  ApiError,
} from '../api.js';

export interface DeterminationFormProps {
  /** Packet id (= encounter id). */
  packetId: string;
  /** Physician token (in-memory). */
  token: string;
  /** Candidate treatment options from the packet (may be empty). */
  candidateTreatmentOptions?: CandidateTreatmentOption[];
  /**
   * Options the engine withheld because a contraindication fired
   * (VAL-PROTO-005). Shown so an absent option is accounted for rather than
   * silently missing — a pregnant patient whose only option was suppressed
   * otherwise sees an empty option list with no explanation.
   */
  withheldTreatmentOptions?: Array<{ optionId: string; ruleId?: string; reason?: string }>;
  /**
   * Server authorization-gate state: whether provisional options are
   * selectable. Defaults to false (the safe clinical default).
   */
  allowProvisionalTreatmentOptions?: boolean;
  /** Called with the updated packet after a successful submission. */
  onRecorded: (packet: Packet) => void;
}

/** A short human-readable authority label for an option authority state. */
function authorityLabel(authorityState: string): string {
  if (authorityState === 'provisional_ai_drafted') return 'provisional — AI-drafted';
  if (authorityState === 'authorized') return 'authorized';
  return authorityState;
}

export function DeterminationForm({
  packetId,
  token,
  candidateTreatmentOptions = [],
  withheldTreatmentOptions = [],
  allowProvisionalTreatmentOptions = false,
  onRecorded,
}: DeterminationFormProps): JSX.Element {
  // No default decision (VAL-DET-009). The form previously opened with
  // 'accept' pre-selected, which made agreeing with the AI packet the
  // physician's resting state: at the review cadence this surface is designed
  // for, a pre-set 'accept' plus a submit button is a rubber stamp with extra
  // steps. The physician must choose. '' is not a valid payload value and
  // submission is refused until a choice is made.
  const [decision, setDecision] = useState<PhysicianDeterminationPayload['decision'] | ''>('');
  const [selectedOptionId, setSelectedOptionId] = useState<string | null>(null);
  const [diagnosis, setDiagnosis] = useState('');
  const [treatment, setTreatment] = useState('');
  const [disposition, setDisposition] = useState('');
  const [notes, setNotes] = useState('');
  const [overrideRationale, setOverrideRationale] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const optionGroupName = useId();

  const hasProvisionalOptions = candidateTreatmentOptions.some(
    (o) => o.authorityState === 'provisional_ai_drafted',
  );

  /** Whether an option is selectable under the current gate state. */
  function optionDisabled(option: CandidateTreatmentOption): boolean {
    return option.authorityState === 'provisional_ai_drafted' && !allowProvisionalTreatmentOptions;
  }

  async function submit(e: React.FormEvent): Promise<void> {
    e.preventDefault();
    setError(null);
    // VAL-DET-009: the decision is the physician's own act of adjudication and
    // has no default, so it must be made explicitly before anything is
    // recorded.
    if (decision === '') {
      setError('Choose a decision: accept, revise, or reject.');
      return;
    }
    // A structured option selection is a complete determination path on its
    // own; the free-text override path requires at least one free-text field
    // (including overrideRationale) (VAL-SURFACE-019/021, VAL-DET-003/005).
    if (
      selectedOptionId === null &&
      diagnosis.trim() === '' &&
      treatment.trim() === '' &&
      disposition.trim() === '' &&
      notes.trim() === '' &&
      overrideRationale.trim() === ''
    ) {
      setError('Select a treatment option, or record at least a diagnosis, treatment, disposition, note, or override rationale.');
      return;
    }
    setSubmitting(true);
    try {
      const payload: PhysicianDeterminationPayload = {
        decision,
        ...(selectedOptionId ? { selectedOptionId } : {}),
        ...(diagnosis.trim() ? { diagnosis: diagnosis.trim() } : {}),
        ...(treatment.trim() ? { treatment: treatment.trim() } : {}),
        ...(disposition.trim() ? { disposition: disposition.trim() } : {}),
        ...(notes.trim() ? { notes: notes.trim() } : {}),
        ...(overrideRationale.trim() ? { overrideRationale: overrideRationale.trim() } : {}),
      };
      const res = await recordDetermination(packetId, token, payload);
      onRecorded(res.packet);
    } catch (e) {
      if (e instanceof ApiError) {
        setError(`Could not record determination (${e.code}). Try again.`);
      } else {
        setError('Could not reach the server. Try again.');
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form
      className="cc-determination"
      onSubmit={submit}
      data-testid="determination-form"
      aria-labelledby="determination-heading"
    >
      <h3 id="determination-heading" className="cc-section-heading">
        Physician determination
      </h3>
      <p className="cc-help" data-testid="determination-help">
        Record your adjudication. This is the physician's own decision — the AI packet above is a
        candidate only and is never a determination.
      </p>

      <label htmlFor="det-decision" className="cc-field-label-block">
        Decision
      </label>
      <select
        id="det-decision"
        className="cc-text-input"
        value={decision}
        onChange={(e) =>
          setDecision(e.target.value as PhysicianDeterminationPayload['decision'] | '')
        }
        data-testid="det-decision"
      >
        <option value="">Choose a decision…</option>
        <option value="accept">Accept candidate packet</option>
        <option value="revise">Revise</option>
        <option value="reject">Reject</option>
      </select>

      {candidateTreatmentOptions.length > 0 ? (
        <fieldset className="cc-treatment-options" data-testid="treatment-options">
          <legend className="cc-field-label-block">Candidate treatment options</legend>
          {hasProvisionalOptions ? (
            <p className="cc-option-warning" role="alert" data-testid="provisional-options-warning">
              Options labelled provisional are AI-drafted and not clinically authorized
              {allowProvisionalTreatmentOptions
                ? '. Selecting one records a provisional determination.'
                : ' and cannot be selected.'}
            </p>
          ) : null}
          <div className="cc-options" role="radiogroup" aria-label="Candidate treatment options">
            {candidateTreatmentOptions.map((option) => {
              const provisional = option.authorityState === 'provisional_ai_drafted';
              const disabled = optionDisabled(option);
              return (
                <label
                  key={option.id}
                  className={`cc-option${selectedOptionId === option.id ? ' cc-option-selected' : ''}${provisional ? ' cc-option-provisional' : ''}${disabled ? ' cc-option-disabled' : ''}`}
                  data-testid={`treatment-option-${option.id}`}
                >
                  <input
                    type="radio"
                    name={optionGroupName}
                    value={option.id}
                    checked={selectedOptionId === option.id}
                    disabled={disabled}
                    onChange={() => setSelectedOptionId(option.id)}
                    data-testid={`treatment-option-input-${option.id}`}
                  />
                  <span className="cc-option-body">
                    <span className="cc-option-label">{option.label}</span>
                    {option.description ? (
                      <span className="cc-option-description">{option.description}</span>
                    ) : null}
                  </span>
                  <span
                    className={`cc-option-authority${provisional ? ' cc-option-authority-provisional' : ''}`}
                    data-testid={`treatment-option-authority-${option.id}`}
                  >
                    {authorityLabel(option.authorityState)}
                  </span>
                </label>
              );
            })}
          </div>
        </fieldset>
      ) : null}

      {/* An option the engine withheld is otherwise invisible: it is simply not
          in the list. Naming it and the rule that removed it lets the physician
          see what was considered (VAL-PROTO-005). */}
      {withheldTreatmentOptions.length > 0 ? (
        <section className="cc-withheld-options" data-testid="withheld-options">
          <h4 className="cc-withheld-heading">Withheld by contraindication</h4>
          <ul className="cc-withheld-list">
            {withheldTreatmentOptions.map((o) => (
              <li key={o.optionId} data-testid={`withheld-option-${o.optionId}`}>
                <span className="cc-withheld-id">{o.optionId}</span>
                {o.reason ? <span className="cc-withheld-reason">{o.reason}</span> : null}
                {o.ruleId ? <span className="cc-withheld-rule">{o.ruleId}</span> : null}
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <label htmlFor="det-diagnosis" className="cc-field-label-block">
        Diagnosis / clinical impression
      </label>
      <textarea
        id="det-diagnosis"
        className="cc-text-input"
        rows={2}
        value={diagnosis}
        onChange={(e) => setDiagnosis(e.target.value)}
        data-testid="det-diagnosis"
      />

      <label htmlFor="det-treatment" className="cc-field-label-block">
        Treatment plan / prescription
      </label>
      <textarea
        id="det-treatment"
        className="cc-text-input"
        rows={2}
        value={treatment}
        onChange={(e) => setTreatment(e.target.value)}
        data-testid="det-treatment"
      />

      <label htmlFor="det-disposition" className="cc-field-label-block">
        Disposition
      </label>
      <input
        id="det-disposition"
        type="text"
        className="cc-text-input"
        value={disposition}
        onChange={(e) => setDisposition(e.target.value)}
        data-testid="det-disposition"
      />

      <label htmlFor="det-notes" className="cc-field-label-block">
        Notes
      </label>
      <textarea
        id="det-notes"
        className="cc-text-input"
        rows={3}
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        data-testid="det-notes"
      />

      <label htmlFor="det-override-rationale" className="cc-field-label-block">
        Override rationale (optional — when none of the candidate options fit)
      </label>
      <textarea
        id="det-override-rationale"
        className="cc-text-input"
        rows={2}
        value={overrideRationale}
        onChange={(e) => setOverrideRationale(e.target.value)}
        data-testid="det-override-rationale"
      />

      <button
        type="submit"
        className="cc-btn cc-btn-primary"
        disabled={submitting}
        data-testid="det-submit"
      >
        {submitting ? 'Recording...' : 'Record determination'}
      </button>
      {/* The irreversible action is this one, not export: recording removes the
          case from the pending queue (list() filters entries with a recorded
          determination). The surface previously warned about export, which is
          reversible, and said nothing here. */}
      <p className="cc-help cc-determination-note" data-testid="determination-irreversible-note">
        Recording removes this case from the review queue.
      </p>

      {error ? (
        <p className="cc-validation" role="alert" data-testid="det-error">
          {error}
        </p>
      ) : null}
    </form>
  );
}
