// @cashclinic/web — physician review surface orchestrator.
//
// Owns the in-memory physician auth state and renders either the access gate
// (when unauthenticated) or the review queue + packet view (when
// authenticated). The physician token lives only in React state — it is
// never persisted to localStorage/sessionStorage (no-PHI-at-rest).
//
// Logout re-gates the surface (VAL-REVIEW-012): the physician can end the
// session, which revokes the token server-side (VAL-AUTH-018) and returns the
// UI to the access gate with no queue or packet content rendered.
//
// The patient intake surface has NO link here; this is rendered only on the
// /review route (App.tsx). Navigating to /review without the credential
// lands on the gate with no review data visible (VAL-AUTH-015,
// VAL-CROSS-009).

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  fetchReviewQueue,
  fetchPacket,
  physicianLogout,
  type QueueSummaryEntry,
  type Packet,
  ApiError,
} from '../api.js';
import { AccessGate } from './AccessGate.js';
import { ReviewQueue } from './ReviewQueue.js';
import { PacketView } from './PacketView.js';

/** The document title for the physician review surface (VAL-A11Y-007). */
const REVIEW_TITLE = 'Physician Review — Cashclinic';

export function PhysicianReview(): JSX.Element {
  // Physician token held in memory only (never persisted).
  const [token, setToken] = useState<string | null>(null);
  const [entries, setEntries] = useState<QueueSummaryEntry[]>([]);
  const [queueLoading, setQueueLoading] = useState(false);
  const [queueError, setQueueError] = useState<string | null>(null);
  const [openPacketId, setOpenPacketId] = useState<string | null>(null);
  const [openPacket, setOpenPacket] = useState<Packet | null>(null);
  const [packetLoading, setPacketLoading] = useState(false);
  const [packetError, setPacketError] = useState<string | null>(null);
  // Server authorization-gate state (feature item 9): whether provisional
  // treatment options are selectable. Communicated by the server on the
  // queue and packet responses; defaults to OFF (the safe clinical default).
  const [allowProvisionalTreatmentOptions, setAllowProvisionalTreatmentOptions] = useState(false);
  // Focus management (VAL-A11Y-004/005): remember the queue entry the packet
  // was opened from so Back restores focus to it. The queue re-renders after
  // every load, so we track the entry *element* by re-querying on restore.
  const lastOpenedFromRef = useRef<string | null>(null);
  const restoreFocusRef = useRef(false);

  // VAL-A11Y-007: the document title reflects the review context while the
  // /review surface is mounted (gate included), and restores on unmount.
  useEffect(() => {
    const previous = document.title;
    document.title = REVIEW_TITLE;
    return () => {
      document.title = previous;
    };
  }, []);

  const loadQueue = useCallback(async (tok: string): Promise<void> => {
    setQueueLoading(true);
    setQueueError(null);
    try {
      const res = await fetchReviewQueue(tok);
      setEntries(res.queue);
      setAllowProvisionalTreatmentOptions(res.allowProvisionalTreatmentOptions ?? false);
      // VAL-QUI-009: if the open packet is no longer in the refreshed queue
      // (determined elsewhere, exported, or TTL-evicted), close the detail
      // pane so the physician sees the placeholder, not stale content.
      setOpenPacketId((current) => {
        if (current !== null && !res.queue.some((e) => e.packetId === current)) {
          setOpenPacket(null);
          return null;
        }
        return current;
      });
    } catch (e) {
      if (e instanceof ApiError && (e.status === 401 || e.status === 403)) {
        // Token no longer valid (expired/revoked) — re-gate (VAL-REVIEW-012,
        // VAL-AUTH-018).
        setToken(null);
        setEntries([]);
        setOpenPacketId(null);
        setOpenPacket(null);
        setQueueError('Your session has ended. Please sign in again.');
      } else {
        setQueueError('Could not load the review queue. Try refreshing.');
      }
    } finally {
      setQueueLoading(false);
    }
  }, []);

  // Load the queue whenever authentication is established.
  useEffect(() => {
    if (token) {
      void loadQueue(token);
    } else {
      // Re-gated: clear all review state so no packet content lingers.
      setEntries([]);
      setOpenPacketId(null);
      setOpenPacket(null);
      setQueueError(null);
      setPacketError(null);
    }
  }, [token, loadQueue]);

  const openPacketById = useCallback(
    async (packetId: string, tok: string): Promise<void> => {
      setPacketLoading(true);
      setPacketError(null);
      try {
        const res = await fetchPacket(packetId, tok);
        setOpenPacket(res.packet);
        setOpenPacketId(packetId);
        setAllowProvisionalTreatmentOptions(res.allowProvisionalTreatmentOptions ?? false);
      } catch (e) {
        if (e instanceof ApiError && (e.status === 401 || e.status === 403)) {
          setToken(null);
          setPacketError('Your session has ended. Please sign in again.');
        } else if (e instanceof ApiError && e.status === 404) {
          setPacketError('That packet is no longer available (it may have been exported or expired).');
          // Refresh the queue so the stale entry disappears.
          void loadQueue(tok);
        } else {
          setPacketError('Could not open that packet. Try again.');
        }
      } finally {
        setPacketLoading(false);
      }
    },
    [loadQueue],
  );

  async function handleLogout(): Promise<void> {
    if (!token) return;
    try {
      await physicianLogout(token);
    } catch {
      // Even if the server call fails, re-gate locally (VAL-REVIEW-012).
    }
    // VAL-REVIEW-012: logout re-gates the review surface; no review content
    // remains visible.
    setToken(null);
  }

  /** Back to the queue: close the detail pane and restore focus to the
   *  originating queue entry (VAL-A11Y-005). The packet stays queued. */
  function handleBack(): void {
    restoreFocusRef.current = true;
    setOpenPacket(null);
    setOpenPacketId(null);
  }

  // VAL-A11Y-005: after Back closes the detail pane, move focus back to the
  // queue entry the packet was opened from (including open-and-immediately-
  // back). Runs after the queue entry has re-rendered as a normal entry.
  useEffect(() => {
    if (!restoreFocusRef.current) return;
    if (openPacketId !== null) return;
    restoreFocusRef.current = false;
    const fromId = lastOpenedFromRef.current;
    lastOpenedFromRef.current = null;
    if (!fromId) return;
    document
      .querySelector<HTMLElement>(`[data-testid="queue-entry-${fromId}"]`)
      ?.focus();
  }, [openPacketId]);

  // ----- Unauthenticated: render the access gate (no review content). -----
  if (!token) {
    return (
      <AccessGate
        onAuthed={(tok) => {
          setToken(tok);
          if (queueError) setQueueError(null);
        }}
      />
    );
  }

  // ----- Authenticated: render the review surface. -----
  return (
    <div className="cc-review-surface" data-testid="review-surface">
      <header className="cc-review-topbar">
        <div className="cc-review-brand">
          <span className="cc-review-mark" aria-hidden="true" />
          <h1>Physician Review</h1>
        </div>
        <div className="cc-review-topbar-actions">
          <button
            type="button"
            className="cc-btn cc-btn-ghost"
            onClick={() => void handleLogout()}
            data-testid="logout"
          >
            Sign out
          </button>
        </div>
      </header>

      {queueError ? (
        <p className="cc-validation" role="alert" data-testid="queue-error">
          {queueError}
        </p>
      ) : null}

      <div className="cc-review-layout">
        {/* Queue landmark: <nav> wrapping the review queue (VAL-A11Y-001). */}
        <nav className="cc-review-queue-nav" aria-label="Review queue">
          <ReviewQueue
            entries={entries}
            loading={queueLoading}
            openPacketId={openPacketId}
            onOpen={(id) => {
              // VAL-A11Y-005: remember where the packet was opened from so
              // Back can restore focus to this entry.
              lastOpenedFromRef.current = id;
              void openPacketById(id, token);
            }}
            onRefresh={() => void loadQueue(token)}
          />
        </nav>

        {/* Detail landmark: <main> wrapping the packet detail area
            (VAL-A11Y-001). */}
        <main className="cc-review-detail" data-testid="review-detail">
          {packetLoading ? (
            // VAL-A11Y-009: async status announced via aria-live.
            <p className="cc-help" data-testid="packet-loading" aria-live="polite">
              Opening packet...
            </p>
          ) : packetError ? (
            <p className="cc-validation" role="alert" data-testid="packet-error">
              {packetError}
            </p>
          ) : openPacket && openPacketId ? (
            <PacketView
              key={openPacketId}
              packetId={openPacketId}
              packet={openPacket}
              token={token}
              allowProvisionalTreatmentOptions={allowProvisionalTreatmentOptions}
              onDeterminationRecorded={(updated) => setOpenPacket(updated)}
              onExported={() => {
                // Export is a download, not a disposition: the server leaves
                // the packet in the queue so both formats can be exported from
                // it. Closing the packet here implied the case was finished
                // and returned the physician to a queue that still contained
                // it. Stay on the packet; refresh the queue so any TTL
                // expiry elsewhere is reflected.
                void loadQueue(token);
              }}
              onBack={handleBack}
            />
          ) : (
            <p className="cc-help cc-detail-placeholder" data-testid="packet-placeholder">
              Select a packet from the queue to review.
            </p>
          )}
        </main>
      </div>
    </div>
  );
}
