// @cashclinic/web — the patient intake flow.
//
// Owns the session lifecycle against the Express intake API:
//   1. Start a session (POST /api/intake/session) -> first question (the
//      presenting-complaint prompt) (VAL-INTAKE-004, VAL-CROSS-009).
//   2. Render ONE question at a time and advance only after a valid answer is
//      submitted (VAL-INTAKE-026). Empty/invalid input is rejected client-side
//      and re-prompted without advancing or fabricating (VAL-CROSS-018).
//   3. Surface a clarifying choice when the engine cannot commit a route
//      (routingState 'awaiting_clarification') (VAL-INTAKE-030).
//   4. Let the presentation sufficiency state drive the patient-facing flow:
//      outside_scope -> redirection; escalation -> stop-and-escalate notice;
//      incomplete_patient -> the engine's next question IS the clarification
//      (VAL-SUFFICIENCY-010).
//   5. Show a completion confirmation when the session completes
//      (VAL-INTAKE-034 — the work/academic-release question and its "for when"
//      follow-up are just two steps in the same one-question-at-a-time flow).
//
// The patient UI exposes NO link or route to the physician review queue or any
// other patient's data (VAL-CROSS-017). Review data lives behind the access
// gate at /review (see App.tsx / AccessGate).

import { useEffect, useRef, useState } from 'react';
import {
  startSession,
  submitAnswer,
  completeSession,
  ApiError,
  type Question,
  type AnswerResponse,
  type Packet,
  type SufficiencyState,
  type RoutingState,
} from '../api.js';
import { QuestionView, type SubmitPayload } from './QuestionView.js';
import { ClarifyView } from './ClarifyView.js';
import { CompletionView } from './CompletionView.js';

type Phase = 'loading' | 'question' | 'clarify' | 'complete' | 'error';

interface FlowState {
  sessionId: string;
  token: string;
  encounterId: string;
  question: Question | null;
  detectedComplaintId: string | null;
  detectedComplaintLabel: string | null;
  routingState: RoutingState;
  sufficiencyState: SufficiencyState;
  packet: Packet | null;
  escalationInstruction: string;
  /** Number of answers submitted so far (for the progress indicator). */
  answeredCount: number;
}

export function PatientIntake(): JSX.Element {
  const [phase, setPhase] = useState<Phase>('loading');
  const [flow, setFlow] = useState<FlowState | null>(null);
  const [validationMessage, setValidationMessage] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const startedRef = useRef(false);

  // Start the session once on mount.
  useEffect(() => {
    if (startedRef.current) return;
    startedRef.current = true;
    void beginSession();
  }, []);

  async function beginSession(): Promise<void> {
    setPhase('loading');
    setError(null);
    try {
      const res = await startSession();
      setFlow({
        sessionId: res.sessionId,
        token: res.token,
        encounterId: res.encounterId,
        question: res.question,
        detectedComplaintId: null,
        detectedComplaintLabel: null,
        routingState: 'unrouted',
        sufficiencyState: 'incomplete_patient',
        packet: null,
        escalationInstruction: '',
        answeredCount: 0,
      });
      setPhase('question');
    } catch (e) {
      setError(errorMessage(e));
      setPhase('error');
    }
  }

  function applyResponse(res: AnswerResponse, prev: FlowState): FlowState {
    return {
      ...prev,
      question: res.question,
      detectedComplaintId: res.detectedComplaintId,
      detectedComplaintLabel: res.detectedComplaintLabel,
      routingState: res.routingState,
      sufficiencyState: res.sufficiencyState,
      packet: res.packet,
      escalationInstruction: res.escalationInstruction,
      answeredCount: prev.answeredCount + 1,
    };
  }

  async function handleSubmit(payload: SubmitPayload): Promise<void> {
    if (!flow) return;
    setValidationMessage(null);
    setSubmitting(true);
    try {
      const body =
        payload.kind === 'structured'
          ? { fieldKey: payload.fieldKey, value: payload.value }
          : { freeText: payload.freeText, fieldKey: payload.fieldKey };
      const res = await submitAnswer(flow.sessionId, flow.token, body);
      const next = applyResponse(res, flow);
      setFlow(next);

      if (res.complete) {
        // The session is complete (either routine completion or an
        // escalation that stopped the pathway). If a packet is already
        // attached, show it; otherwise fetch it.
        if (res.packet) {
          setPhase('complete');
        } else {
          await finalize(next);
        }
      } else if (res.routingState === 'awaiting_clarification') {
        setPhase('clarify');
      } else if (isOutsideScope(res)) {
        // outside_scope: do not continue routine questions; show redirection.
        setPhase('question');
      } else {
        setPhase('question');
      }
    } catch (e) {
      if (e instanceof ApiError && (e.status === 400 || e.status === 409)) {
        // The server rejected the answer (e.g. invalid value, malformed
        // compound shape, already-completed session). Surface the message and
        // STAY on the current question — do not advance, do not fabricate
        // (VAL-CROSS-018).
        setValidationMessage(e.message || 'That answer was not accepted. Please try again.');
      } else {
        setError(errorMessage(e));
        setPhase('error');
      }
    } finally {
      setSubmitting(false);
    }
  }

  async function finalize(current: FlowState): Promise<void> {
    try {
      const res = await completeSession(current.sessionId, current.token);
      setFlow((prev) => (prev ? { ...prev, packet: res.packet } : prev));
      setPhase('complete');
    } catch (e) {
      setError(errorMessage(e));
      setPhase('error');
    }
  }

  async function handleClarify(choice: string): Promise<void> {
    if (!flow) return;
    setValidationMessage(null);
    setSubmitting(true);
    try {
      const res = await submitAnswer(flow.sessionId, flow.token, {
        fieldKey: 'clarify_complaint',
        value: choice,
      });
      const next = applyResponse(res, flow);
      setFlow(next);
      if (res.complete) {
        if (res.packet) setPhase('complete');
        else await finalize(next);
      } else {
        setPhase('question');
      }
    } catch (e) {
      if (e instanceof ApiError && e.status === 400) {
        setValidationMessage(e.message || 'That choice was not accepted.');
      } else {
        setError(errorMessage(e));
        setPhase('error');
      }
    } finally {
      setSubmitting(false);
    }
  }

  function handleInvalid(msg: string): void {
    // VAL-CROSS-018: empty/invalid input — show a validation cue and stay on
    // the current question. No API call is made, so no advance and no
    // fabricated value is recorded.
    setValidationMessage(msg);
  }

  function restart(): void {
    startedRef.current = false;
    setFlow(null);
    setValidationMessage(null);
    setError(null);
    void beginSession();
  }

  // --- Render ---

  if (phase === 'loading' || !flow) {
    return (
      <div className="cc-screen cc-loading" role="status" aria-live="polite">
        <p>Starting your intake session...</p>
      </div>
    );
  }

  if (phase === 'error') {
    return (
      <div className="cc-screen cc-error" role="alert">
        <h2>Something went wrong</h2>
        <p className="cc-error-detail">{error ?? 'Unknown error'}</p>
        <button type="button" className="cc-btn cc-btn-primary" onClick={restart}>
          Start over
        </button>
      </div>
    );
  }

  if (phase === 'complete') {
    return (
      <CompletionView
        packet={flow.packet}
        encounterId={flow.encounterId}
        detectedComplaintLabel={flow.detectedComplaintLabel}
        sufficiencyState={flow.sufficiencyState}
        escalationInstruction={flow.escalationInstruction}
        onRestart={restart}
      />
    );
  }

  // outside_scope: show a redirection message instead of routine questions
  // (VAL-SUFFICIENCY-010). The patient is not asked more clinical questions.
  if (isOutsideScope(flow) && flow.routingState === 'out_of_scope') {
    return (
      <div className="cc-screen cc-redirect" role="status">
        <h2>This is outside our intake scope</h2>
        <p>
          Based on what you described, your concern doesn't match the conditions this service
          handles. Please contact your physician's office or an appropriate care provider for
          next steps.
        </p>
        {flow.detectedComplaintLabel ? null : null}
        <button type="button" className="cc-btn cc-btn-primary" onClick={restart}>
          Start a new intake
        </button>
      </div>
    );
  }

  // Escalation that stopped the pathway: surface the instruction and stop.
  if (flow.escalationInstruction && flow.sufficiencyState === 'escalation_required') {
    return (
      <div className="cc-screen cc-escalation" role="alert">
        <h2>Urgent follow-up is needed</h2>
        <p className="cc-escalation-instruction" data-testid="escalation-instruction">
          {flow.escalationInstruction}
        </p>
        <p>
          Your responses have been forwarded for priority physician review. Please follow the
          instruction above and do not continue routine intake questions.
        </p>
        <button type="button" className="cc-btn cc-btn-primary" onClick={restart}>
          Start a new intake
        </button>
      </div>
    );
  }

  if (phase === 'clarify' && flow.question) {
    return (
      <ClarifyView
        question={flow.question}
        onSubmit={handleClarify}
        onInvalid={handleInvalid}
        submitting={submitting}
        validationMessage={validationMessage}
        step={flow.answeredCount + 1}
      />
    );
  }

  if (!flow.question) {
    // No next question and not complete — fetch the packet to finalize.
    return (
      <div className="cc-screen cc-finishing" role="status">
        <p>Finalizing your intake...</p>
        <button type="button" className="cc-btn cc-btn-primary" onClick={() => void finalize(flow)}>
          Finish
        </button>
      </div>
    );
  }

  return (
    <div className="cc-screen cc-intake">
      <header className="cc-intake-header">
        <h1>Cashclinic Patient Intake</h1>
        <ProgressBadge answered={flow.answeredCount} complaintLabel={flow.detectedComplaintLabel} />
      </header>

      <main className="cc-intake-body">
        <QuestionView
          question={flow.question}
          complaintLabel={flow.detectedComplaintLabel}
          onSubmit={handleSubmit}
          onInvalid={handleInvalid}
          submitting={submitting}
          step={flow.answeredCount + 1}
        />
        {validationMessage ? (
          <p className="cc-validation" role="alert" data-testid="validation-message">
            {validationMessage}
          </p>
        ) : null}
        {flow.sufficiencyState === 'incomplete_patient' ? (
          <p className="cc-flow-hint">
            We need a bit more information to complete your intake.
          </p>
        ) : null}
      </main>

      <footer className="cc-intake-footer">
        <p className="cc-privacy-note">
          Your answers are used only for this intake and are not stored permanently.
        </p>
        {/* No link to any physician or review surface (VAL-CROSS-017). */}
      </footer>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isOutsideScope(s: { routingState: RoutingState; sufficiencyState: SufficiencyState }): boolean {
  return s.routingState === 'out_of_scope' || s.sufficiencyState === 'outside_scope';
}

function errorMessage(e: unknown): string {
  if (e instanceof Error) return e.message;
  return String(e);
}

function ProgressBadge({
  answered,
  complaintLabel,
}: {
  answered: number;
  complaintLabel: string | null;
}): JSX.Element {
  return (
    <div className="cc-progress" aria-label="intake progress">
      <span className="cc-progress-count" data-testid="progress-answered">
        {answered} answered
      </span>
      {complaintLabel ? (
        <span className="cc-progress-complaint" data-testid="progress-complaint">
          {complaintLabel}
        </span>
      ) : null}
    </div>
  );
}
