// @cashclinic/web — physician access gate.
//
// This is the boundary that prevents a patient (or anyone without the
// physician credential) from reaching the physician review queue or any
// patient's packet (VAL-AUTH-015, VAL-CROSS-009). The patient intake UI has
// NO link to this route; navigating to /review from the patient context lands
// here, and NO queue or packet content is rendered until the correct
// physician password is supplied (VAL-AUTH-016 grants, VAL-AUTH-017 denies).
//
// The gate is controlled by the PhysicianReview orchestrator: a successful
// login calls `onAuthed(token)`, which lifts the physician token into memory
// and reveals the review surface. The token is never persisted to
// localStorage/sessionStorage (no-PHI-at-rest privacy model).

import { useEffect, useRef, useState } from 'react';
import { physicianLogin, ApiError } from '../api.js';

export interface AccessGateProps {
  /** Called with the physician token on a successful login. */
  onAuthed: (token: string) => void;
}

/** Selector for the focusable controls inside the gate dialog. */
const FOCUSABLE =
  'input:not([disabled]), button:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function AccessGate({ onAuthed }: AccessGateProps): JSX.Element {
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  // VAL-A11Y-013: move initial focus into the dialog (the password field) so
  // keyboard users start inside the gate, not on the page behind it.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    const first = dialog.querySelector<HTMLElement>(FOCUSABLE);
    (first ?? dialog).focus();
  }, []);

  // VAL-A11Y-013: focus trap — Tab / Shift+Tab cycle within the dialog and
  // never leak focus to content behind the gate. The gate renders alone, so
  // any wrap simply cycles the gate's own controls.
  function handleKeyDown(e: React.KeyboardEvent<HTMLDivElement>): void {
    if (e.key !== 'Tab') return;
    const dialog = dialogRef.current;
    if (!dialog) return;
    // Note: no offsetParent visibility filter — jsdom has no layout, and the
    // gate renders alone so every matched control is visible by construction.
    const focusables = Array.from(dialog.querySelectorAll<HTMLElement>(FOCUSABLE));
    if (focusables.length === 0) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    const active = document.activeElement;
    if (e.shiftKey) {
      if (active === first || !dialog.contains(active)) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (active === last || !dialog.contains(active)) {
        e.preventDefault();
        first.focus();
      }
    }
  }

  async function submit(e: React.FormEvent): Promise<void> {
    e.preventDefault();
    setError(null);
    if (password.trim() === '') {
      // VAL-AUTH-017: an empty/blank password keeps the surface locked.
      setError('Enter the physician access password.');
      return;
    }
    setSubmitting(true);
    try {
      const res = await physicianLogin(password);
      // VAL-AUTH-016: correct password unlocks the review surface.
      onAuthed(res.token);
    } catch (e) {
      if (e instanceof ApiError) {
        // VAL-AUTH-017: wrong password is denied; no review content exposed.
        setError('Access denied. Check the physician password and try again.');
      } else {
        setError('Could not reach the access service. Try again.');
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div
      className="cc-screen cc-review-gate"
      role="dialog"
      aria-modal="true"
      aria-labelledby="gate-label"
      ref={dialogRef}
      onKeyDown={handleKeyDown}
    >
      <h1 id="gate-label">Physician Access</h1>
      <p className="cc-help">
        The review queue is restricted. Enter the physician access password to continue.
      </p>
      <form onSubmit={submit} className="cc-gate-form" data-testid="gate-form">
        <label htmlFor="gate-password" className="cc-field-label-block">
          Physician password
        </label>
        <input
          id="gate-password"
          type="password"
          className="cc-text-input"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          autoComplete="current-password"
          aria-required
          data-testid="gate-password"
        />
        <button
          type="submit"
          className="cc-btn cc-btn-primary"
          disabled={submitting}
          data-testid="gate-submit"
        >
          {submitting ? 'Checking...' : 'Enter review'}
        </button>
        {error ? (
          <p className="cc-validation" role="alert" data-testid="gate-error">
            {error}
          </p>
        ) : null}
      </form>
    </div>
  );
}
