// @cashclinic/web — render a single protocol question and collect its answer.
//
// The component is purely presentational + validating. It does NOT submit to
// the API itself; on a valid submit it calls `onSubmit(value | freeTextBody)`.
// On an empty/invalid submit it calls `onInvalid(message)` and stays on the
// current question (VAL-CROSS-018: empty/invalid required input does NOT
// advance and does NOT fabricate a value).
//
// Input rendering is driven by `question.answerType`:
//   text     -> textarea (chief_complaint and other free-text fields)
//   boolean  -> Yes / No buttons
//   select   -> radio buttons from question.options (exact tokens submitted)
//   number   -> number input
//   compound -> the three shared-block compound fields (pmh_conditions,
//               medications_list, allergies_list) get a structured row form so
//               the flow stays deterministic and LLM-free; any other compound
//               field gets a free-text textarea submitted via the de-id ->
//               inference pipeline.

import { useEffect, useState } from 'react';
import type { Question } from '../api.js';

export type SubmitPayload =
  | { kind: 'structured'; fieldKey: string; value: unknown }
  | { kind: 'freetext'; freeText: string; fieldKey?: string };

interface QuestionViewProps {
  question: Question;
  /** The detected complaint label, shown for context once routed. */
  complaintLabel?: string | null;
  onSubmit: (payload: SubmitPayload) => void;
  onInvalid: (message: string) => void;
  /** Whether a submission is currently in flight (disables inputs). */
  submitting?: boolean;
  /** The 1-based step number for the progress indicator. */
  step?: number;
}

export function QuestionView({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting = false,
  step,
}: QuestionViewProps): JSX.Element {
  // Complaint-specific multi-part prompts are answered one control at a time.
  // Shared compound blocks have dedicated forms below; keep those forms in
  // charge of their own wrapper/entry validation.
  if (question.parts && !isDedicatedCompoundQuestion(question)) {
    return (
      <StructuredPartsQuestion
        question={question}
        complaintLabel={complaintLabel}
        onSubmit={onSubmit}
        onInvalid={onInvalid}
        submitting={submitting}
        step={step}
      />
    );
  }
  switch (question.answerType) {
    case 'boolean':
      return (
        <BooleanQuestion
          question={question}
          complaintLabel={complaintLabel}
          onSubmit={onSubmit}
          submitting={submitting}
          step={step}
        />
      );
    case 'select':
      return (
        <SelectQuestion
          question={question}
          complaintLabel={complaintLabel}
          onSubmit={onSubmit}
          submitting={submitting}
          step={step}
        />
      );
    case 'number':
      return (
        <NumberQuestion
          question={question}
          complaintLabel={complaintLabel}
          onSubmit={onSubmit}
          onInvalid={onInvalid}
          submitting={submitting}
          step={step}
        />
      );
    case 'compound':
      return (
        <CompoundQuestion
          question={question}
          complaintLabel={complaintLabel}
          onSubmit={onSubmit}
          onInvalid={onInvalid}
          submitting={submitting}
          step={step}
        />
      );
    case 'text':
    default:
      return (
        <TextQuestion
          question={question}
          complaintLabel={complaintLabel}
          onSubmit={onSubmit}
          onInvalid={onInvalid}
          submitting={submitting}
          step={step}
        />
      );
  }
}

function isDedicatedCompoundQuestion(question: Question): boolean {
  return (
    question.answerType === 'compound' &&
    (question.fieldKey === 'pmh_conditions' ||
      question.fieldKey === 'medications_list' ||
      question.fieldKey === 'allergies_list')
  );
}

/** Render every independent fact in a structured group with its own control. */
function StructuredPartsQuestion({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const [values, setValues] = useState<Record<string, unknown>>({});
  const [partIndex, setPartIndex] = useState(0);
  useEffect(() => {
    setValues({});
    setPartIndex(0);
  }, [question.fieldKey]);
  const active = (part: NonNullable<Question['parts']>[number]): boolean =>
    !part.conditionalOn || values[part.conditionalOn.key] === part.conditionalOn.equals;

  const activeParts = (question.parts ?? []).filter(active);
  const part = activeParts[partIndex] ?? activeParts[activeParts.length - 1];

  const submit = (): void => {
    if (!part) return;
    const value = values[part.key];
    if (part.required !== false && value === undefined) {
      onInvalid(`Please answer: ${part.label}`);
      return;
    }
    if (value !== undefined) onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { [part.key]: value } });
    if (partIndex < activeParts.length - 1) setPartIndex((index) => index + 1);
  };

  const set = (key: string, value: unknown): void => setValues((prev) => ({ ...prev, [key]: value }));

  return (
    <fieldset className="cc-question cc-question-structured" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <div className="cc-structured-parts">
        {part ? (
            <div className="cc-structured-part" key={part.key}>
              <h3 className="cc-part-label" data-testid={`part-label-${question.fieldKey}-${part.key}`}>
                {part.label}{part.required !== false ? ' *' : ''}
              </h3>
              {part.answerType === 'boolean' ? (
                <div className="cc-boolean-row" role="group" aria-label={part.label}>
                  <button type="button" className={`cc-btn cc-btn-option ${values[part.key] === true ? 'cc-option-selected' : ''}`} onClick={() => set(part.key, true)}>Yes</button>
                  <button type="button" className={`cc-btn cc-btn-option ${values[part.key] === false ? 'cc-option-selected' : ''}`} onClick={() => set(part.key, false)}>No</button>
                </div>
              ) : part.answerType === 'select' ? (
                <select id={`part-${question.fieldKey}-${part.key}`} className="cc-select-input" value={(values[part.key] as string | undefined) ?? ''} onChange={(e) => set(part.key, e.target.value)}>
                  <option value="" disabled>Select an answer</option>
                  {(part.options ?? []).map((option) => <option key={option} value={option}>{option.replace(/_/g, ' ')}</option>)}
                </select>
              ) : part.answerType === 'number' ? (
                <input id={`part-${question.fieldKey}-${part.key}`} className="cc-number-input" type="number" min="0" onChange={(e) => set(part.key, e.target.value === '' ? undefined : Number(e.target.value))} />
              ) : (
                <input id={`part-${question.fieldKey}-${part.key}`} className="cc-text-input" type="text" value={(values[part.key] as string | undefined) ?? ''} onChange={(e) => set(part.key, e.target.value)} />
              )}
            </div>
          ) : null}
      </div>
      <button type="button" className="cc-btn cc-btn-primary" onClick={submit}>Continue</button>
    </fieldset>
  );
}

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

function FieldLabel({
  question,
  complaintLabel,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  step?: number;
}): JSX.Element {
  return (
    <div className="cc-field-label">
      {typeof step === 'number' ? (
        <div className="cc-step-tag" aria-label={`step ${step}`}>
          Step {step}
        </div>
      ) : null}
      <h2 className="cc-question-text" id={`q-${question.fieldKey}-label`}>
        {question.text}
      </h2>
      {complaintLabel ? (
        <div className="cc-complaint-context">
          Routed: <strong>{complaintLabel}</strong>
        </div>
      ) : null}
      {question.required ? (
        <span className="cc-required-mark" aria-label="required">
          {' '}
          *required
        </span>
      ) : null}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Text question (also used for the presenting chief-complaint prompt)
// ---------------------------------------------------------------------------

function TextQuestion({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const [value, setValue] = useState('');
  const isChief = question.fieldKey === 'chief_complaint';

  const submit = (): void => {
    const trimmed = value.trim();
    if (question.required && trimmed === '') {
      onInvalid('Please enter a response before continuing.');
      return;
    }
    if (isChief) {
      // The presenting complaint is captured as patient_reported and routed
      // deterministically by the engine (no LLM needed for routing).
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: trimmed });
    } else {
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: trimmed });
    }
  };

  return (
    <fieldset className="cc-question cc-question-text" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <textarea
        className="cc-text-input"
        aria-labelledby={`q-${question.fieldKey}-label`}
        aria-required={question.required}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        rows={isChief ? 4 : 3}
        placeholder={isChief ? 'Describe what brings you in today...' : 'Type your answer...'}
        data-testid={`input-${question.fieldKey}`}
      />
      <button type="button" className="cc-btn cc-btn-primary" onClick={submit} data-testid={`submit-${question.fieldKey}`}>
        Continue
      </button>
    </fieldset>
  );
}

// ---------------------------------------------------------------------------
// Boolean question (Yes / No)
// ---------------------------------------------------------------------------

function BooleanQuestion({
  question,
  complaintLabel,
  onSubmit,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  // Booleans can never be "empty" — a click always yields true/false — so no
  // invalid path is needed (VAL-CROSS-018 still holds: no advance without a
  // value).
  const submit = (v: boolean): void => {
    onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: v });
  };
  return (
    <fieldset className="cc-question cc-question-boolean" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <div className="cc-boolean-row" role="group" aria-labelledby={`q-${question.fieldKey}-label`}>
        <button
          type="button"
          className="cc-btn cc-btn-option"
          onClick={() => submit(true)}
          data-testid={`input-${question.fieldKey}-yes`}
        >
          Yes
        </button>
        <button
          type="button"
          className="cc-btn cc-btn-option"
          onClick={() => submit(false)}
          data-testid={`input-${question.fieldKey}-no`}
        >
          No
        </button>
      </div>
    </fieldset>
  );
}

// ---------------------------------------------------------------------------
// Select question (radio buttons from exact option tokens)
// ---------------------------------------------------------------------------

function SelectQuestion({
  question,
  complaintLabel,
  onSubmit,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const [choice, setChoice] = useState<string | null>(null);
  const options = question.options ?? [];

  const submit = (): void => {
    if (question.required && choice === null) {
      // onInvalid not wired here because selection drives the submit button;
      // keep the guard for completeness.
      return;
    }
    if (choice !== null) {
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: choice });
    }
  };

  return (
    <fieldset className="cc-question cc-question-select" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <div className="cc-options" role="radiogroup" aria-labelledby={`q-${question.fieldKey}-label`}>
        {options.map((opt) => (
          <label
            key={opt}
            className={`cc-option ${choice === opt ? 'cc-option-selected' : ''}`}
            data-testid={`option-${question.fieldKey}-${opt}`}
          >
            <input
              type="radio"
              name={question.fieldKey}
              value={opt}
              checked={choice === opt}
              onChange={() => setChoice(opt)}
              aria-required={question.required}
            />
            <span>{optionLabel(opt)}</span>
          </label>
        ))}
      </div>
      <button
        type="button"
        className="cc-btn cc-btn-primary"
        onClick={submit}
        disabled={choice === null}
        data-testid={`submit-${question.fieldKey}`}
      >
        Continue
      </button>
    </fieldset>
  );
}

/** Humanize an option token like `not_pregnant_not_nursing` -> "not pregnant not nursing". */
function optionLabel(token: string): string {
  return token.replace(/_/g, ' ');
}

// ---------------------------------------------------------------------------
// Number question
// ---------------------------------------------------------------------------

function NumberQuestion({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const [raw, setRaw] = useState('');
  const submit = (): void => {
    const trimmed = raw.trim();
    if (trimmed === '') {
      // Never fabricate a value. A blank numeric field is not coerced to 0
      // (VAL-CROSS-018). The patient must enter a number to advance; if they
      // have no value, that is a backend skip gap (see discoveredIssues).
      onInvalid('Please enter a number.');
      return;
    }
    const num = Number(trimmed);
    if (Number.isNaN(num) || !Number.isFinite(num)) {
      onInvalid('Please enter a valid number.');
      return;
    }
    onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: num });
  };
  return (
    <fieldset className="cc-question cc-question-number" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <input
        type="text"
        inputMode="decimal"
        className="cc-number-input"
        aria-labelledby={`q-${question.fieldKey}-label`}
        aria-required={question.required}
        value={raw}
        onChange={(e) => setRaw(e.target.value)}
        placeholder="Enter a number..."
        data-testid={`input-${question.fieldKey}`}
      />
      <button type="button" className="cc-btn cc-btn-primary" onClick={submit} data-testid={`submit-${question.fieldKey}`}>
        Continue
      </button>
    </fieldset>
  );
}

// ---------------------------------------------------------------------------
// Compound question
// ---------------------------------------------------------------------------

function CompoundQuestion({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  // The three shared-block compound fields get deterministic structured forms
  // (no LLM). Any other compound field falls back to free-text through the
  // de-id -> inference pipeline.
  if (question.fieldKey === 'pmh_conditions') {
    return (
      <PmhConditionsForm
        question={question}
        complaintLabel={complaintLabel}
        onSubmit={onSubmit}
        onInvalid={onInvalid}
        submitting={submitting}
        step={step}
      />
    );
  }
  if (question.fieldKey === 'medications_list') {
    return (
      <MedicationsForm
        question={question}
        complaintLabel={complaintLabel}
        onSubmit={onSubmit}
        onInvalid={onInvalid}
        submitting={submitting}
        step={step}
      />
    );
  }
  if (question.fieldKey === 'allergies_list') {
    return (
      <AllergiesForm
        question={question}
        complaintLabel={complaintLabel}
        onSubmit={onSubmit}
        onInvalid={onInvalid}
        submitting={submitting}
        step={step}
      />
    );
  }
  return (
    <FreeTextCompound
      question={question}
      complaintLabel={complaintLabel}
      onSubmit={onSubmit}
      onInvalid={onInvalid}
      submitting={submitting}
      step={step}
    />
  );
}

// A free-text fallback for complaint-specific compound questions (e.g. sinus
// congestion/facial/fever). Submitted via the de-id -> inference pipeline so
// the engine stays the source of truth and no value is fabricated.
function FreeTextCompound({
  question,
  complaintLabel,
  onSubmit,
  onInvalid,
  submitting,
  step,
}: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const [value, setValue] = useState('');
  const submit = (): void => {
    const trimmed = value.trim();
    if (question.required && trimmed === '') {
      onInvalid('Please describe your answer before continuing.');
      return;
    }
    onSubmit({ kind: 'freetext', freeText: trimmed, fieldKey: question.fieldKey });
  };
  return (
    <fieldset className="cc-question cc-question-compound-freetext" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <textarea
        className="cc-text-input"
        aria-labelledby={`q-${question.fieldKey}-label`}
        aria-required={question.required}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        rows={3}
        placeholder="Describe in your own words..."
        data-testid={`input-${question.fieldKey}`}
      />
      <button type="button" className="cc-btn cc-btn-primary" onClick={submit} data-testid={`submit-${question.fieldKey}`}>
        Continue
      </button>
    </fieldset>
  );
}

// --- pmh_conditions: { conditions: [{ name, kind }] } ---

function PmhConditionsForm(props: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const { question, complaintLabel, onSubmit, onInvalid, submitting, step } = props;
  const [rows, setRows] = useState<Array<{ name: string; kind: string }>>([{ name: '', kind: 'chronic' }]);

  const update = (i: number, patch: Partial<{ name: string; kind: string }>): void => {
    setRows((prev) => prev.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  };
  const addRow = (): void => setRows((prev) => [...prev, { name: '', kind: 'chronic' }]);
  const removeRow = (i: number): void =>
    setRows((prev) => prev.filter((_, idx) => idx !== i));

  const submit = (none: boolean): void => {
    if (none) {
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { conditions: [] } });
      return;
    }
    const cleaned = rows
      .map((r) => ({ name: r.name.trim(), kind: r.kind.trim() }))
      .filter((r) => r.name !== '');
    if (question.required && cleaned.length === 0) {
      onInvalid('Add at least one condition, or choose "None of these".');
      return;
    }
    for (const r of cleaned) {
      if (r.kind === '') {
        onInvalid('Choose acute or chronic for each condition.');
        return;
      }
    }
    onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { conditions: cleaned } });
  };

  return (
    <fieldset className="cc-question cc-question-pmh" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <p className="cc-help">List any medical conditions you are currently being treated for.</p>
      {rows.map((r, i) => (
        <div className="cc-row" key={i} data-testid={`pmh-row-${i}`}>
          <input
            type="text"
            placeholder="Condition name"
            value={r.name}
            onChange={(e) => update(i, { name: e.target.value })}
            aria-label={`condition ${i + 1} name`}
            data-testid={`pmh-name-${i}`}
          />
          <select
            value={r.kind}
            onChange={(e) => update(i, { kind: e.target.value })}
            aria-label={`condition ${i + 1} kind`}
            data-testid={`pmh-kind-${i}`}
          >
            <option value="chronic">chronic</option>
            <option value="acute">acute</option>
          </select>
          <button type="button" className="cc-btn cc-btn-ghost" onClick={() => removeRow(i)} aria-label={`remove condition ${i + 1}`}>
            Remove
          </button>
        </div>
      ))}
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-ghost" onClick={addRow} data-testid="pmh-add">
          + Add condition
        </button>
      </div>
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-primary" onClick={() => submit(false)} data-testid={`submit-${question.fieldKey}`}>
          Continue
        </button>
        <button type="button" className="cc-btn cc-btn-ghost" onClick={() => submit(true)} data-testid={`none-${question.fieldKey}`}>
          None of these
        </button>
      </div>
    </fieldset>
  );
}

// --- medications_list: { medications: [{ name, forCondition? }] } ---

function MedicationsForm(props: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const { question, complaintLabel, onSubmit, onInvalid, submitting, step } = props;
  const [rows, setRows] = useState<Array<{ name: string; forCondition: string }>>([{ name: '', forCondition: '' }]);

  const update = (i: number, patch: Partial<{ name: string; forCondition: string }>): void => {
    setRows((prev) => prev.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  };
  const addRow = (): void => setRows((prev) => [...prev, { name: '', forCondition: '' }]);
  const removeRow = (i: number): void =>
    setRows((prev) => prev.filter((_, idx) => idx !== i));

  const submit = (none: boolean): void => {
    if (none) {
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { medications: [] } });
      return;
    }
    const cleaned = rows
      .map((r) => ({ name: r.name.trim(), forCondition: r.forCondition.trim() }))
      .filter((r) => r.name !== '');
    if (question.required && cleaned.length === 0) {
      onInvalid('Add at least one medication, or choose "None".');
      return;
    }
    const payload = cleaned.map((r) =>
      r.forCondition === '' ? { name: r.name } : { name: r.name, forCondition: r.forCondition },
    );
    onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { medications: payload } });
  };

  return (
    <fieldset className="cc-question cc-question-meds" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <p className="cc-help">List your current prescription medications.</p>
      {rows.map((r, i) => (
        <div className="cc-row" key={i} data-testid={`med-row-${i}`}>
          <input
            type="text"
            placeholder="Medication name"
            value={r.name}
            onChange={(e) => update(i, { name: e.target.value })}
            aria-label={`medication ${i + 1} name`}
            data-testid={`med-name-${i}`}
          />
          <input
            type="text"
            placeholder="For which condition? (optional)"
            value={r.forCondition}
            onChange={(e) => update(i, { forCondition: e.target.value })}
            aria-label={`medication ${i + 1} for condition`}
            data-testid={`med-for-${i}`}
          />
          <button type="button" className="cc-btn cc-btn-ghost" onClick={() => removeRow(i)} aria-label={`remove medication ${i + 1}`}>
            Remove
          </button>
        </div>
      ))}
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-ghost" onClick={addRow} data-testid="med-add">
          + Add medication
        </button>
      </div>
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-primary" onClick={() => submit(false)} data-testid={`submit-${question.fieldKey}`}>
          Continue
        </button>
        <button type="button" className="cc-btn cc-btn-ghost" onClick={() => submit(true)} data-testid={`none-${question.fieldKey}`}>
          None
        </button>
      </div>
    </fieldset>
  );
}

// --- allergies_list: { entries: [{ substance, reaction, type }] } ---

function AllergiesForm(props: {
  question: Question;
  complaintLabel?: string | null;
  onSubmit: (p: SubmitPayload) => void;
  onInvalid: (m: string) => void;
  submitting: boolean;
  step?: number;
}): JSX.Element {
  const { question, complaintLabel, onSubmit, onInvalid, submitting, step } = props;
  const [rows, setRows] = useState<Array<{ substance: string; reaction: string; type: string }>>([
    { substance: '', reaction: '', type: 'allergy' },
  ]);

  const update = (i: number, patch: Partial<{ substance: string; reaction: string; type: string }>): void => {
    setRows((prev) => prev.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  };
  const addRow = (): void =>
    setRows((prev) => [...prev, { substance: '', reaction: '', type: 'allergy' }]);
  const removeRow = (i: number): void =>
    setRows((prev) => prev.filter((_, idx) => idx !== i));

  const submit = (none: boolean): void => {
    if (none) {
      onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { entries: [] } });
      return;
    }
    const cleaned = rows
      .map((r) => ({ substance: r.substance.trim(), reaction: r.reaction.trim(), type: r.type.trim() }))
      .filter((r) => r.substance !== '');
    if (question.required && cleaned.length === 0) {
      onInvalid('Add at least one allergy, or choose "None".');
      return;
    }
    for (const r of cleaned) {
      if (r.reaction === '') {
        onInvalid('Describe the reaction for each allergy.');
        return;
      }
      if (r.type !== 'allergy' && r.type !== 'intolerance') {
        onInvalid('Each entry must be an allergy or an intolerance.');
        return;
      }
    }
    onSubmit({ kind: 'structured', fieldKey: question.fieldKey, value: { entries: cleaned } });
  };

  return (
    <fieldset className="cc-question cc-question-allergies" disabled={submitting}>
      <FieldLabel question={question} complaintLabel={complaintLabel} step={step} />
      <p className="cc-help">
        List medication allergies or intolerances and the reaction you had. Mark each as an allergy or an intolerance.
      </p>
      {rows.map((r, i) => (
        <div className="cc-row cc-row-3" key={i} data-testid={`allergy-row-${i}`}>
          <input
            type="text"
            placeholder="Substance"
            value={r.substance}
            onChange={(e) => update(i, { substance: e.target.value })}
            aria-label={`allergy ${i + 1} substance`}
            data-testid={`allergy-substance-${i}`}
          />
          <input
            type="text"
            placeholder="Reaction"
            value={r.reaction}
            onChange={(e) => update(i, { reaction: e.target.value })}
            aria-label={`allergy ${i + 1} reaction`}
            data-testid={`allergy-reaction-${i}`}
          />
          <select
            value={r.type}
            onChange={(e) => update(i, { type: e.target.value })}
            aria-label={`allergy ${i + 1} type`}
            data-testid={`allergy-type-${i}`}
          >
            <option value="allergy">allergy</option>
            <option value="intolerance">intolerance</option>
          </select>
          <button type="button" className="cc-btn cc-btn-ghost" onClick={() => removeRow(i)} aria-label={`remove allergy ${i + 1}`}>
            Remove
          </button>
        </div>
      ))}
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-ghost" onClick={addRow} data-testid="allergy-add">
          + Add allergy
        </button>
      </div>
      <div className="cc-row-actions">
        <button type="button" className="cc-btn cc-btn-primary" onClick={() => submit(false)} data-testid={`submit-${question.fieldKey}`}>
          Continue
        </button>
        <button type="button" className="cc-btn cc-btn-ghost" onClick={() => submit(true)} data-testid={`none-${question.fieldKey}`}>
          None
        </button>
      </div>
    </fieldset>
  );
}
